INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7776', 'spa', 'shu''al — zorro o chacal; pequeño cánido salvaje que merodea entre ruinas, saquea viñedos y come carroña', 'Sustantivo masculino que abarca los pequeños cánidos salvajes del Levante: tanto zorros como chacales, que el hebreo bíblico no distingue de manera consistente. Sansón capturó trescientos de ellos para quemar los campos de trigo de los filisteos (Jue 15:4), cifra que probablemente apunte a chacales, más gregarios que los solitarios zorros. El Cantar de los Cantares advierte de las «zorras pequeñas que echan a perder las viñas» (Cnt 2:15), imagen entrañable de amenazas menores que arruinan lo tierno. Ezequiel compara a los falsos profetas de Israel con zorros entre ruinas (Ez 13:4), Lamentaciones lamenta que los zorros ronden el desolado monte Sion (Lm 5:18), y el salmista declara que los malvados serán «presa de zorros» (Sal 63:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7778', 'spa', 'Portero o guardian apostado en una puerta para controlar el acceso, especialmente en el Templo o las puertas de la ciudad.', 'Portero o guardian apostado en una puerta para controlar el acceso, especialmente en el Templo o las puertas de la ciudad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7779', 'spa', 'Aplastar, herir; golpear con fuerza causando lesión, especialmente en la cabeza o el talón; usado en Génesis 3:15', 'Este verbo es célebre por Génesis 3:15, donde aparece dos veces en la maldición de Dios sobre la serpiente: la simiente de la mujer aplastará la cabeza de la serpiente, mientras que la serpiente herirá el talón del ser humano. El término describe un golpe violento que causa daño sin necesariamente matar. En Job 9:17 se usa para referirse al poder abrumador de Dios que aplasta a Job en la tempestad. Este pasaje de Génesis ha sido leído mesiánicamente por muchas tradiciones, donde el golpe a la cabeza se entiende como un ataque decisivo y el del talón como una herida menor: una promesa cósmica de victoria final a través del sufrimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7782', 'spa', 'Shofar; trompeta de cuerno de carnero usada en la guerra, la asamblea, la adoración y la teofanía; ocasionalmente el cuerno mismo como objeto.', 'Shofar; trompeta de cuerno de carnero usada en la guerra, la asamblea, la adoración y la teofanía; ocasionalmente el cuerno mismo como objeto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7783', 'spa', 'desbordar, regar abundantemente—causar superabundancia, especialmente de líquidos', 'Este verbo Piel/Hifil describe causar desbordamiento o abundancia, particularmente de líquidos. El Salmo 65:9 representa a Dios regando la tierra abundantemente, usando imágenes agrícolas de provisión divina. Joel lo usa dos veces (2:24, 3:13) para cubas que desbordan de vino y aceite, símbolos de bendición restaurada o de abundancia en juicio de cosecha. El término enfatiza superabundancia más allá de la mera suficiencia, bendición líquida derramándose fuera de los recipientes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7784', 'spa', 'Calle, plaza pública; espacio abierto dentro de una ciudad donde la gente se reúne y se realiza comercio', 'Este sustantivo designa las calles o plazas públicas de una ciudad, los espacios abiertos donde se desarrolla la vida comunitaria. Proverbios 7:8 describe al joven pasando por la calle cerca de la esquina de la adúltera. Eclesiastés 12:4-5 menciona la calle como el lugar donde las puertas se cierran y las voces se apagan en la vejez. Cantares 3:2 muestra a la novia buscando a su amado por calles y plazas. A diferencia del callejón estrecho (מָבוֹא), este término refiere al espacio amplio donde acontecen los encuentros de la vida pública, tanto inocentes como peligrosos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7785', 'spa', 'Pierna o muslo — la parte inferior de la pierna de una persona o la parte superior trasera de un animal sacrificial', 'Pierna o muslo — la parte inferior de la pierna de una persona o la parte superior trasera de un animal sacrificial');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7789', 'spa', 'Contemplar, mirar fijamente; acechar o espiar con intención hostil; cantar o entonar (variante poética rara)', 'Contemplar, mirar fijamente; acechar o espiar con intención hostil; cantar o entonar (variante poética rara)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7791a', 'spa', 'muro—barrera defensiva o envolvente de piedra o ladrillo', 'Este sustantivo denota un muro, típicamente en contextos poéticos. Génesis 49:22 lo usa en la bendición de José sobre ramas que se extienden sobre un muro. Segunda de Samuel 22:30 (= Salmo 18:29) describe saltar sobre un muro con la ayuda de Dios, imagen de proeza militar o superación de obstáculos. El término puede ser un aramaísmo, relacionado con la palabra aramea común para muro, apareciendo en textos poéticos hebreos en lugar de en prosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7792', 'spa', 'Muro, muralla (arameo); murallas de una ciudad, especialmente las de Jerusalén en tiempos de Esdras', 'Este sustantivo arameo aparece únicamente en Esdras 4, en las cartas que se oponen a la reconstrucción de las murallas de Jerusalén. El contexto es profundamente político: los adversarios escriben al rey persa advirtiendo que si se completan las murallas, la ciudad se rebelará y dejará de pagar tributo. En el antiguo Cercano Oriente, las murallas no eran meras estructuras defensivas: simbolizaban autonomía, seguridad y poder político. La oposición a la reconstrucción revela cuán amenazante resultaba una Jerusalén fortificada para los pueblos circundantes. Las murallas significaban libertad y la capacidad de una ciudad para sostenerse por sí misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7793', 'spa', 'Shur — region en la frontera suroeste de Canaan cerca de Egipto, asociada con travesias deserticas y los relatos patriarcales.', 'Nombre propio que designa una region en el noreste del Sinai, a lo largo de la frontera suroeste de Canaan y el limite oriental de Egipto. Shur aparece vinculado a la huida de Agar (Gen 16:7, ''el camino de Shur''), al territorio donde Abraham peregrinaba (Gen 20:1) y como punto de referencia del territorio ismaelita (Gen 25:18). Tras el Exodo, Israel entro en el ''desierto de Shur'' (Exod 15:22). El nombre podria derivar de una palabra que significa ''muro'', posiblemente en referencia a una linea de fortificaciones fronterizas egipcias a traves del istmo de Suez, aunque esto sigue siendo objeto de debate.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7794', 'spa', 'Buey, toro; una res individual usada en contextos agrícolas, legales, sacrificiales y poéticos.', 'Buey, toro; una res individual usada en contextos agrícolas, legales, sacrificiales y poéticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7797', 'spa', 'Exultar, regocijarse grandemente — expresar gozo intenso, frecuentemente en contextos de pacto, escatológicos o de adoración', 'Exultar, regocijarse grandemente — expresar gozo intenso, frecuentemente en contextos de pacto, escatológicos o de adoración');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7799', 'spa', 'Lirio, loto; cualquier flor semejante al lirio, usada para la belleza botánica, la ornamentación arquitectónica y la imaginería romántica. El שׁוּשַׁן', 'Lirio, loto; cualquier flor semejante al lirio, usada para la belleza botánica, la ornamentación arquitectónica y la imaginería romántica. El שׁוּשַׁן / שׁוֹשַׁנָּה (shushan/shoshannah) probablemente abarca varias flores semejantes al lirio, posiblemente incluyendo el loto. Tomada del egipcio (sššn), la palabra florece en los pasajes más evocadores de la Escritura. En el Cantar de los Cantares, la amada es ''un lirio entre espinos'' (2:2), el amado apacienta ''entre los lirios'' (2:16; 6:3) y sus labios son ''lirios que destilan mirra'' (5:13). El Templo de Salomón presentaba capiteles en forma de lirio en sus columnas (1 R 7:19, 22) y un ''mar'' con borde en forma de flor de lirio (1 R 7:26). Oseas 14:6 promete que Israel restaurado ''florecerá como el lirio.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7800', 'spa', 'Susa (שׁוּשַׁן), la antigua capital de Elam y residencia invernal de los reyes persas', 'Susa (שׁוּשַׁן), la antigua capital de Elam y residencia invernal de los reyes persas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7802', 'spa', 'Lirio; flor semejante al lirio, usada en símiles de belleza y como término técnico en los títulos de salmos', 'Este sustantivo designa al lirio o flores similares, aunque la identificación botánica exacta sigue siendo debatida (posiblemente el iris u otras flores). En Cantares se convierte en una tierna metáfora: la amada es como un lirio entre espinos (2:2), y se habla del «lirio de los valles» (2:1). Sorprendentemente, también aparece en los títulos de los Salmos 60 y 80 como término técnico musical o litúrgico («según Susán Edut», es decir, «el lirio del testimonio»). La flor en sí evoca belleza delicada, pureza y tal vez la renovación primaveral. El uso técnico en los salmos ya era oscuro para los traductores antiguos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7803', 'spa', 'Sutélaj; nombre propio de un descendiente de Efraín y ancestro de clan', 'Este es el nombre de un prominente ancestro efraimita que aparece en las listas genealógicas de Números 26 y 1 Crónicas 7. Fue hijo de Efraín y dio su nombre al clan de los sutelaítas. El nombre presenta ligeras variaciones ortográficas que reflejan distintas tradiciones manuscritas o pronunciaciones dialectales. Como ocurre con muchos nombres de clan, Sutélaj representa tanto a un individuo ancestral como al grupo familiar extenso que trazaba su descendencia desde él, integrado en la estructura tribal de Efraín.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7804', 'spa', 'Librar o rescatar del peligro, verbo arameo (raíz Shafel) usado exclusivamente en Daniel para la liberación divina', 'Verbo arameo que significa «librar» o «rescatar», derivado de la raíz Shafel (causativa) de un término acadio que significa «escapar». Usado exclusivamente en Daniel, esta palabra porta un peso teológico poderoso: describe la capacidad de Dios para rescatar a sus siervos de peligro mortal — el horno de fuego (Dn 3:15-28) y el foso de los leones (Dn 6:14-28). La pregunta teológica «¿Qué dios podrá libraros de mis manos?» (Dn 3:15) convierte este verbo en piedra de toque de la soberanía divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7805', 'spa', 'mirar fijamente, abrasar—observar intensamente, posiblemente con efecto dañino', 'Este verbo Qal describe mirar o contemplar algo, con posibles matices de visión dañina. Job lo usa dos veces: el ojo que vio a la persona malvada no la verá de nuevo (20:9), y para un sendero que ninguna ave de rapiña ha vislumbrado (28:7). Cantares 1:6 puede significar que el sol ''me miró'' (causando oscurecimiento), aunque algunos interpretan esto como abrasar. El rango semántico abarca observación y posible visión dañina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7806', 'spa', 'Ser torcido o trenzado; usado exclusivamente del hilo de lino en la construcción del tabernáculo (participio Hofal)', 'Ser torcido o trenzado; usado exclusivamente del hilo de lino en la construcción del tabernáculo (participio Hofal)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7810', 'spa', 'Soborno — dádiva entregada para corromper el juicio, pervertir la justicia u obtener favor ilícito; universalmente condenado en la ley', 'Soborno — dádiva entregada para corromper el juicio, pervertir la justicia u obtener favor ilícito; universalmente condenado en la ley');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7811', 'spa', 'nadar, empapar—moverse a través del agua o hacer completamente mojado', 'Este verbo se relaciona con nadar o empapar con líquido. Isaías 25:11 representa a Dios derribando al orgulloso ''como el nadador extiende para nadar'', usando movimientos de natación como metáfora. El Salmo 6:6 habla de empapar una cama con lágrimas durante la noche. La forma Hifil transmite sentido causativo—hacer que algo nade o empapar completamente. La conexión semántica entre nadar y empapar reside en la saturación con líquido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7812', 'spa', 'Postrarse, inclinarse en adoración u homenaje; también: inclinarse (Qal), abatir o abrumar (Hifil)', 'Uno de los verbos de adoración más físicamente vívidos de la Biblia hebrea. La forma Hitpael —con diferencia la más frecuente— describe la postración completa de una persona ante Dios o un superior humano, con el rostro en tierra. Abraham se inclina ante los hititas (Gn 23:7), todas las naciones se postran ante el Señor (Sal 22:27). El alemán anbeten («adorar») y el español postrarse captan la reverencia, mientras que el suajili -sujudu refleja el cognado islámico para la misma postura corporal. En contadas ocasiones, el Qal imperativo significa simplemente «inclínate» (Is 51:23), y el Hifil en Proverbios 12:25 describe la ansiedad que «abate» el corazón, una llamativa extensión metafórica de este verbo postural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7814', 'spa', 'Risa (gozosa o burlona); hazmerreír u objeto de escarnio; diversión, entretenimiento. שְׂחוֹק abarca todo el espectro emocional de la risa: desde el g', 'Risa (gozosa o burlona); hazmerreír u objeto de escarnio; diversión, entretenimiento. שְׂחוֹק abarca todo el espectro emocional de la risa: desde el gozo que llena la boca de los exiliados restaurados (Sal 126:2) hasta la amarga burla que recae sobre Jeremías (Jer 20:7). Derivado de שָׂחַק (''reír, jugar''), este sustantivo se reparte casi equitativamente entre la risa gozosa y el escarnio despectivo, con una aparición sapiencial que significa ''diversión''. Eclesiastés explora la ambigüedad más profundamente: ''Dije de la risa: es locura'' (Ecl 2:2), y ''mejor es la tristeza que la risa'' (Ecl 7:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7817', 'spa', 'Inclinarse, ser humillado, agacharse; en Hitpael, estar abatido de espíritu; en Hifil, abatir o humillar', 'Inclinarse, ser humillado, agacharse; en Hitpael, estar abatido de espíritu; en Hifil, abatir o humillar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7819a', 'spa', 'Degollar, matar (un animal); principalmente sacrificio ritual; en Nifal, ser degollado; también de la matanza violenta de personas.', 'Degollar, matar (un animal); principalmente sacrificio ritual; en Nifal, ser degollado; también de la matanza violenta de personas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7820', 'spa', 'degollar, batir; como participio: batido, martillado (del oro aplicado sobre escudos)', 'La raiz significa degollar o batir, con el sentido originario probable de ''golpear, desollar''. En las cinco apariciones registradas, solo se documenta el participio pasivo Qal, que describe oro martillado o batido aplicado sobre escudos grandes y pequenos. El lujoso arsenal de Salomon (1 R 10:16-17) y su paralelo en Cronicas (2 Cr 9:15-16) emplean esta forma. El cognado acadio shakhatu (''desollar'') ilumina la violencia fisica que subyace al termino, incluso en su aplicacion metalurgica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7822', 'spa', 'Divieso o úlcera cutánea inflamada; usado para las llagas de las plagas, erupciones leprosas y aflicciones dolorosas en la piel humana o animal. שְׁחִ', 'Divieso o úlcera cutánea inflamada; usado para las llagas de las plagas, erupciones leprosas y aflicciones dolorosas en la piel humana o animal. שְׁחִין designa una lesión cutánea dolorosa e inflamada — un divieso o úlcera que brota en la superficie del cuerpo. En Éxodo 9:9-11 aparece como una de las plagas de Egipto, afectando tanto a personas como a animales. Levítico 13:18-23 lo trata como una condición potencialmente leprosa que requiere examen sacerdotal. La ''úlcera de Egipto'' (Dt 28:27) se convierte en maldición del pacto, mientras que las llagas atormentadoras de Job (Job 2:7) y el divieso mortal de Ezequías (2 R 20:7; Is 38:21) lo muestran como señal de aflicción física severa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7826', 'spa', 'shachal — león (poético); león feroz y maduro en la literatura sapiencial y profética', 'Uno de varios términos hebreos para «león», shachal pertenece al registro poético elevado y aparece exclusivamente en Job, Salmos, Proverbios y Oseas, nunca en la prosa narrativa. Evoca al depredador feroz y adulto: Dios persigue a Job «como un león» (Job 10:16), y el rugido del shachal enmudece cuando Dios quiebra los dientes de los malvados (Job 4:10). El salmista promete que el justo pisoteará al shachal y al leoncillo (Sal 91:13), y el perezoso protesta que hay un león en el camino (Pr 26:13). Oseas lo emplea dos veces para el juicio de Dios sobre Israel: «Seré como un león para Efraín» (Os 5:14; 13:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7832', 'spa', 'Reir, jugar, celebrar; en Qal, reir con desprecio o gozo; en Piel, jugar, divertirse, festejar o actuar', 'Reir, jugar, celebrar; en Qal, reir con desprecio o gozo; en Piel, jugar, divertirse, festejar o actuar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7833', 'spa', 'moler, pulverizar; reducir a polvo fino mediante triturado o aplastamiento, ya sea incienso, piedras o enemigos', 'Este verbo describe la acción de moler algo hasta convertirlo en partículas finas o polvo. En Éxodo 30:36 se refiere a pulverizar incienso para uso en el tabernáculo. Job 14:19 lo emplea poéticamente: las aguas desgastan las piedras, imagen de una erosión lenta e implacable. En 2 Samuel 22:43 y Salmo 18:42, David declara haber molido a sus enemigos como polvo de la tierra. Es una reducción total: tomar algo sólido y convertirlo en polvo, ya sea mediante un triturado paciente o un aplastamiento violento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7834', 'spa', 'Nubes tenues, cielos o firmamento; raramente polvo fino — de la raíz que significa ''pulverizar''', 'Nubes tenues, cielos o firmamento; raramente polvo fino — de la raíz que significa ''pulverizar''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7836', 'spa', 'Buscar con ahínco, escudriñar diligentemente; madrugar en pos de algo — denominativo de ''alba''', 'El verbo שָׁחַר es denominativo de שַׁחַר (''alba''), y lleva consigo la vívida connotación de levantarse con las primeras luces para buscar algo con urgencia. En su forma Piel dominante describe con mayor frecuencia la búsqueda ferviente de Dios: ''Oh Dios, tú eres mi Dios; de madrugada te busco'' (Sal 63:1), pero también abarca la búsqueda diligente de la disciplina (Pr 13:24) y los asnos monteses que buscan presa al amanecer (Job 24:5). La metáfora del alba le confiere una intensidad emocional que lo distingue de verbos de búsqueda más neutros como בִּקֵּשׁ o דָּרַשׁ.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7837', 'spa', 'Alba, amanecer; la primera luz de la mañana, usado literal y figuradamente para esperanza, esplendor o juicio', 'Alba, amanecer; la primera luz de la mañana, usado literal y figuradamente para esperanza, esplendor o juicio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7838', 'spa', 'Negro, oscuro; usado para describir el color del cabello, caballos y la tez en textos rituales, profeticos y poeticos.', 'Adjetivo que significa ''negro'' u ''oscuro'', aplicado al color fisico en tres contextos distintos. En Levitico 13:31 y 13:37, la ley sacerdotal lo emplea para evaluar el color del cabello en el diagnostico de enfermedades cutaneas: el cabello negro indica salud. El Cantar de los Cantares lo usa tanto para la autodescripcion de la amada (''morena soy'', 1:5) como para los cabellos del amado (''sus cabellos son negros'', 5:11). La vision de Zacarias presenta caballos negros (6:2, 6:6) como agentes del proposito divino. El termino ''morena'' en Cantares 1:5 capta la calidez de la expresion mejor que un simple ''negra'', sugiriendo una belleza curtida por el sol mas que un mero color.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7843', 'spa', 'Destruir, arruinar, corromper, obrar perversamente; ser corrompido o arruinado (Nifal); ser defectuoso (Hofal)', 'Un verbo de devastación y deterioro que abarca tanto la destrucción física como la corrupción moral. En el Hifil y el Piel describe la aniquilación de Sodoma por parte de Dios (Gn 19:14), la destrucción de toda carne por el diluvio (Gn 6:17) y la devastación de ciudades por ejércitos. Pero también designa la ruina moral: la humanidad corrompiendo su camino sobre la tierra (Gn 6:12), Israel actuando corruptamente con ídolos (Dt 4:16). Los cognados árabes saḥata («extirpar») y etiópico saḥata («dañar, violar») confirman la antigua doble trayectoria de la raíz hacia la devastación física y la moral. Las formas pasivas del Nifal y el Hofal completan el cuadro con estados de ruina, deterioro o defecto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7844', 'spa', 'corrupto, falta—moralmente contaminado o que contiene defectos (arameo)', 'Este participio pasivo arameo describe algo corrupto, defectuoso o moralmente contaminado. Daniel 2:9 habla de preparar una ''palabra corrupta'' para engañar al rey. Daniel 6:4 (apareciendo dos veces) describe a funcionarios que buscan encontrar falta o corrupción en Daniel pero no encuentran ninguna. El término captura tanto la corrupción moral como el defecto o falta técnica, ya sea en el habla, la conducta o el carácter. Aparece solo en las secciones arameas de Daniel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7845', 'spa', 'Fosa o trampa; frecuentemente figurado para el Seol o la tumba; raramente corrupción o destrucción en sentido abstracto', 'Fosa o trampa; frecuentemente figurado para el Seol o la tumba; raramente corrupción o destrucción en sentido abstracto');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7847', 'spa', 'Desviarse, extraviarse — especialmente de la infidelidad conyugal o la desviacion moral.', 'El verbo שָׂטָה aparece solo seis veces en la Biblia hebrea, pero sus contextos son vividos y memorables. Cuatro ocurrencias pertenecen al ritual de la sota en Numeros 5, donde una esposa ''se desvia'' en infidelidad conyugal; el nombre mismo del ritual deriva de esta raiz. Las dos restantes se encuentran en Proverbios, donde se advierte al joven que ''se aparte'' del camino de la mujer seductora (4:15) y que no deje que su corazon ''se incline'' hacia los caminos de ella (7:25). El cognado arameo סְטָא y los paralelos etiopicos confirman el significado central de desviacion de un camino recto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7848', 'spa', 'Acacia: árbol espinoso del desierto cuya madera duradera se empleó para los utensilios sagrados del tabernáculo', 'Acacia: árbol espinoso del desierto cuya madera duradera se empleó para los utensilios sagrados del tabernáculo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7849', 'spa', 'Esparcir, extender — estirar algo en una superficie abierta; usado literal y figuradamente de la expansion divina.', 'Verbo que significa extender o esparcir algo sobre una superficie abierta. Su uso mas vivido se encuentra en Numeros 11:32, donde los israelitas esparcieron las codornices alrededor del campamento para secarlas. En 2 Samuel 17:19, la mujer de Bahurim extiende grano sobre un pozo para ocultar a Jonatan y Ahimaas. La intensificacion Piel aparece en Salmo 88:9, donde se extienden las manos en oracion. Job 12:23 ofrece una notable extension figurada: Dios ''extiende'' a las naciones, expandiendo su territorio antes de abatirlas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7851', 'spa', 'Sitim; topónimo al este del Jordán, último campamento de Israel antes de cruzar, y un valle cerca de Jerusalén', 'שִׁטִּים (literalmente ''las acacias'') designa dos lugares en las Escrituras. El principal es el campamento final de Israel en las llanuras de Moab, al este del Jordán, donde el pueblo pecó con mujeres moabitas (Nm 25:1) y desde donde Josué envió espías a Jericó (Jos 2:1; 3:1). Miqueas 6:5 recuerda el trayecto ''desde Sitim hasta Gilgal'' como resumen de los actos salvíficos de Dios. Joel 3:18 menciona un ''Valle de Sitim'' cerca de Jerusalén, probablemente el Wadi es-Sant.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7852', 'spa', 'Guardar rencor, albergar animosidad; sentimiento hostil persistente que puede desembocar en persecucion.', 'Verbo que expresa una hostilidad profunda y duradera, no un estallido momentaneo de ira sino una disposicion arraigada de enemistad. El rencor de Esau contra Jacob tras perder la bendicion (Gen 27:41) constituye el uso paradigmatico: animosidad sostenida nacida de un agravio personal. Los hermanos de Jose temen este mismo resentimiento latente (Gen 50:15). En los Salmos y Job, el verbo pasa a describir una persecucion implacable: los enemigos del salmista lo odian ''con furor airado'' (Sal 55:4), y Job acusa a Dios de volverse perseguidor (Job 16:9; 30:21). Es mas que simple odio; es un rencor sostenido con intencion hostil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7853', 'spa', 'Acusar, actuar como adversario; verbo denominativo de ''satán'', que describe el papel de oposición legal o espiritual.', 'Verbo denominativo derivado del sustantivo ''satán'' (adversario), que significa actuar como acusador u oponente. Las seis ocurrencias se concentran en los Salmos y Zacarías, evocando una escena de tribunal donde se formula una acusación. En Zacarías 3:1, el Satán se coloca a la diestra del sumo sacerdote Josué ''para acusarle'' — el infinitivo constructo capta la postura deliberadamente adversarial. Los Salmos lo emplean para describir a enemigos humanos que devuelven bien con acusación (Sal 109:4) y que actúan como fiscales hostiles (Sal 71:13; 109:20, 29). El registro forense-legal del verbo se mantiene constante en todas sus apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7854', 'spa', 'Adversario, acusador; el Satán: un oponente humano, fiscal en juicio, o el Acusador celestial en la corte de Dios', 'Adversario, acusador; el Satán: un oponente humano, fiscal en juicio, o el Acusador celestial en la corte de Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7857', 'spa', 'Desbordar, inundar o arrasar; tambien enjuagar o lavar. Se usa para agua literal, invasion metaforica y purificacion ritual', 'Desbordar, inundar o arrasar; tambien enjuagar o lavar. Se usa para agua literal, invasion metaforica y purificacion ritual');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7858', 'spa', 'Inundación, torrente, avalancha de agua; usado literalmente para tormentas y figuradamente para la ira divina o la calamidad.', 'Sustantivo masculino que designa una irrupción repentina y arrolladora de agua — un torrente o riada. Job 38:25 lo emplea literalmente para el cauce que Dios abre a la tormenta. Pero sus apariciones más impactantes son figuradas: Nahúm 1:8 advierte que Dios acabará con sus adversarios ''con inundación desbordante'', mientras Daniel 9:26 y 11:22 lo aplican a ejércitos que arrasan como aguas desbocadas. Proverbios 27:4 lo empareja con la ira — ''inundación de furor'' — capturando una fuerza emocional incontenible. El término abarca tanto el fenómeno natural como la fuerza destructiva irresistible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7860', 'spa', 'Oficial, funcionario o capataz; administrador subordinado encargado de organizar, supervisar o hacer cumplir órdenes', 'Oficial, funcionario o capataz; administrador subordinado encargado de organizar, supervisar o hacer cumplir órdenes');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7862', 'spa', 'regalo, tributo—presente ofrecido como homenaje a un superior', 'Este sustantivo denota un regalo o tributo, particularmente ofrendas de homenaje traídas a un poder superior. Los Salmos hablan de naciones trayendo tributo a Dios (68:29, 76:11), mientras que Isaías 18:7 profetiza pueblos distantes trayendo regalos al Señor de los ejércitos. El término enfatiza la naturaleza tributaria de tales regalos—no intercambio sino reconocimiento de soberanía y sumisión. Estas ofrendas reconocen la autoridad divina o real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7868', 'spa', 'anciano(s); término arameo para los líderes canosos de la comunidad, usado como título administrativo en Esdras', 'Verbo arameo que significa ''ser canoso, encanecido'', empleado exclusivamente como participio con función sustantiva: ''ancianos''. Funciona como título administrativo técnico en las secciones arameas de Esdras, designando a los líderes de la comunidad judía que supervisaron la reconstrucción del Segundo Templo. Estos ancianos negociaron con funcionarios persas (Esd 5:5, 9) y recibieron autorización real para continuar la obra (6:7-8, 14). El término es paralelo al hebreo זָקֵן, pero pertenece al vocabulario administrativo arameo del período persa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7872', 'spa', 'Canas, cabeza encanecida; por metonimia, la vejez misma, especialmente en la frase ''buena vejez''', 'Canas, cabeza encanecida; por metonimia, la vejez misma, especialmente en la frase ''buena vejez''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7875', 'spa', 'cal, encalado; óxido de calcio producido al quemar piedra caliza o huesos, usado para recubrir piedras o como metáfora de consumo total', 'Este sustantivo designa la cal o el encalado, una sustancia blanca producida al quemar piedra caliza o huesos. En Deuteronomio 27:2-4, se ordena a los israelitas levantar grandes piedras y recubrirlas con cal antes de escribir la ley sobre ellas, creando una superficie blanca, duradera y legible. Amós 2:1 la emplea en un juicio contra Moab por quemar los huesos del rey de Edom hasta convertirlos en cal. Isaías 33:12 compara a los pueblos con espinos cortados y quemados hasta hacerse cal. El recubrimiento blanco cumple funciones prácticas y lleva un peso simbólico de pureza, permanencia y, en contextos de fuego, consumo total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7878', 'spa', 'Meditar, reflexionar, hablar o quejarse; abarcando todo el arco desde la reflexión silenciosa hasta el lamento vocal y el discurso público', 'Meditar, reflexionar, hablar o quejarse; abarcando todo el arco desde la reflexión silenciosa hasta el lamento vocal y el discurso público');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7879', 'spa', 'Queja o lamento ante Dios; meditación profunda o reflexión; también habla o discurso ordinario. שִׂיחַ es un sustantivo ricamente estratificado deriva', 'Queja o lamento ante Dios; meditación profunda o reflexión; también habla o discurso ordinario. שִׂיחַ es un sustantivo ricamente estratificado derivado de la raíz que significa ''reflexionar, meditar, quejarse''. En su sentido más frecuente, es el clamor crudo y sin filtro del angustiado derramado ante Dios: la súplica desgarrada de Ana (1 S 1:16), el amargo lamento de Job (Job 7:13; 9:27; 10:1) y el salmista que ''derrama su queja delante de Jehová'' (Sal 142:2). Sin embargo, la misma palabra puede suavizarse hasta convertirse en meditación silenciosa, como cuando la ''meditación'' del salmista sobre las obras de Dios le resulta dulce (Sal 104:34). En una sola aparición (2 R 9:11), simplemente significa ''habla'' — discurso ordinario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7880', 'spa', 'arbusto, matorral; vegetación silvestre del campo o del desierto, especialmente plantas leñosas pequeñas', 'Este sustantivo se refiere a arbustos o matorrales, las plantas leñosas del campo y del desierto. Génesis 2:5 lo usa en el relato de la creación: ningún arbusto del campo había brotado aún antes de que Dios enviara la lluvia. En Génesis 21:15, Agar coloca a su hijo bajo uno de los arbustos en el desierto de Beerseba, buscando sombra y quizás ocultándolo. Job 30:4-7 habla de marginados que se refugian entre los matorrales, subrayando su extrema pobreza. Son plantas de tierras no cultivadas que ofrecen escaso refugio, pero suficiente para esconder a un niño o albergar a los desamparados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7881', 'spa', 'meditación, queja—reflexión mental sobre un tema, frecuentemente las Escrituras', 'Este sustantivo femenino denota meditación o reflexión, particularmente sobre la ley de Dios. Salmo 119:97 y 99 celebran la Torá como la meditación del salmista, objeto de continuo compromiso mental. Job 15:4 lo usa para ''queja ante Dios'' o posiblemente meditación/oración, aunque el sentido es debatido. El término captura atención mental enfocada, ya sea meditación devocional sobre las Escrituras o queja de oración llevando preocupaciones ante Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7882', 'spa', 'fosa, zanja—hoyo cavado o trampa', 'Este sustantivo femenino denota una fosa o zanja cavada, frecuentemente como trampa o peligro. Salmo 57:6 y 119:85 hablan de enemigos cavando fosas para atrapar a los justos. Jeremías 18:22 menciona fosas cavadas para atrapar al profeta. La imagen involucra consistentemente trampas hostiles, cavando hoyos ocultos para capturar o dañar al inocente. El término aparece en contextos de conspiración traicionera y la necesidad de liberación divina de tales ardides.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7883', 'spa', 'Sijor; nombre de un cuerpo de agua en la frontera de Egipto, probablemente un brazo del Nilo o un arroyo fronterizo oriental', 'Este nombre geográfico designa un cuerpo de agua asociado con la frontera de Egipto. Josué 13:3 lo menciona como límite sur de Israel. 1 Crónicas 13:5 habla de reunir a Israel «desde el Sijor de Egipto hasta Lebo-hamat». Isaías 23:3 se refiere poéticamente al «grano de Sijor, la cosecha del Nilo», tratándolos como paralelos. Jeremías 2:18 cuestiona por qué Israel bebería las aguas de Sijor al buscar alianza con Egipto. La etimología tradicional lo deriva de palabras que significan «agua negra», quizás por las oscuras aguas del Nilo. Sijor representa la frontera egipcia, un marcador político y geográfico del extremo sur de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7887', 'spa', 'Silo -- el centro cultual israelita en Efrain donde estuvo el tabernaculo desde la conquista hasta los inicios de la monarquia', 'Silo -- el centro cultual israelita en Efrain donde estuvo el tabernaculo desde la conquista hasta los inicios de la monarquia');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7888', 'spa', 'El silonita — adjetivo gentilicio que identifica a alguien procedente de Silo, aplicado especialmente al profeta Ahías.', 'Adjetivo gentilicio que significa ''el de Silo'', usado casi exclusivamente para identificar al profeta Ahías, quien profetizó la división del reino de Salomón. El artículo definido aparece siempre unido — ''el silonita'' — marcándolo como epíteto reconocido. Cinco de las seis ocurrencias se refieren a Ahías (1 R 11:29; 12:15; 15:29; 2 Cr 9:29; 10:15), mientras que 1 Crónicas 9:5 emplea el término colectivamente para habitantes de Silo que se asentaron en Jerusalén tras el exilio. La ortografía varía ligeramente entre Reyes y Crónicas, reflejando la fluidez ortográfica normal en los adjetivos gentilicios hebreos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7891', 'spa', 'Cantar; también como participio: cantor o músico del templo, especialmente los coristas levíticos de Crónicas-Esdras-Nehemías.', 'Cantar; también como participio: cantor o músico del templo, especialmente los coristas levíticos de Crónicas-Esdras-Nehemías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7892a', 'spa', 'Canto, composición musical — pieza lírica para la adoración, la celebración o la expresión artística.', 'Canto, composición musical — pieza lírica para la adoración, la celebración o la expresión artística.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7892b', 'spa', 'Cántico, oda; composición poética formal cantada en alabanza, celebración o conmemoración de los actos divinos', 'El sustantivo femenino שִׁירָה (shirah) designa un cántico u oda: una pieza poética formal compuesta para el culto comunitario o la celebración nacional. Su ejemplo más célebre es el Cántico del Mar: «Entonces Moisés y los hijos de Israel cantaron este cántico al SEÑOR» (Éx 15:1). El Cántico del Pozo emplea la misma fórmula (Nm 21:17). Deuteronomio lo aplica al cántico-testamento de Moisés, ordenado como testimonio contra Israel (Dt 31:19, 21-22, 30). En Jueces 5:12, Débora es convocada a «entonar un cántico». Estos usos enmarcan שִׁירָה como una obra literaria compuesta con función litúrgica y conmemorativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7895', 'spa', 'Sisac, el faraón egipcio (Shoshenq I) que invadió Judá durante el reinado de Roboam', 'Nombre propio Sisac, forma hebrea del egipcio Shoshenq I, fundador de la XXII dinastía. Aparece primero como el faraón que dio refugio a Jeroboam cuando este huyó de Salomón (1 R 11:40), y luego como el invasor que atacó Jerusalén en el quinto año de Roboam, llevándose los tesoros del templo y del palacio real (1 R 14:25; 2 Cr 12:2-9). Su campaña militar está atestiguada de forma independiente por su relieve de victoria en el templo de Karnak. En español se lo conoce convencionalmente como «Sisac».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7896', 'spa', 'Poner, colocar, situar; hacer o convertir en un estado; designar; en pasiva: ser puesto o impuesto.', 'Poner, colocar, situar; hacer o convertir en un estado; designar; en pasiva: ser puesto o impuesto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7898', 'spa', 'shayit — espinos, cardos; maleza espinosa que señala desolación y juicio divino', 'Sustantivo masculino colectivo para arbustos espinosos o cardos, que aparece exclusivamente en Isaías y siempre emparejado con shamir («espinas») formando la fórmula profética shamir washayit. Este par de espinas es la imagen distintiva de Isaías para la ruina agrícola y el juicio divino: una viña antes cultivada invadida por cardos (Is 5:6), tierras compradas por mil monedas de plata ahora sin valor y ahogadas en espinos (Is 7:23-25), y la maldad ardiendo entre espinas como un incendio forestal (Is 9:18; 10:17). En Isaías 27:4, Dios declara que si espinos y cardos se alzaran contra él en batalla, los consumiría con fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7901', 'spa', 'Acostarse, reclinarse, dormir; eufemismo para relaciones sexuales; Hifil: acostar a alguien; también: volcar (líquido)', 'שָׁכַב es el verbo postural universal de la Biblia hebrea para la posición horizontal: acostarse para dormir, yacer en la muerte y el eufemismo característico para las relaciones sexuales. El coreano distingue sistemáticamente nuwotda («se reclinó») de dongchimhaetda («yació sexualmente»), mientras que el español separa acostarse de yacer con. La misma raíz en árabe (sakaba) significa solo «verter», acepción que sobrevive en una enigmática ocurrencia de Job 38:37 sobre volcar los cántaros del cielo. El Hifil añade escenas domésticas tiernas de acostar a un niño, y el raro Hofal aparece en los cuadros del inframundo de Ezequiel, donde los guerreros «son tendidos» entre los muertos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7902', 'spa', 'Acto de yacer; emisión seminal (en contextos de procreación o pureza); también una capa o recubrimiento (de rocío)', 'Sustantivo femenino que aparece exclusivamente en forma constructa, con dos sentidos concretos bien diferenciados. En Levítico designa ''un yacer de simiente'', es decir, la emisión seminal en el contexto de las leyes de pureza que regulan el contacto sexual y las emisiones corporales (Lv 15:16-18, 32; 19:20; 22:4; Nm 5:13). La expresión שִׁכְבַת זֶרַע es una fórmula legal técnica. El segundo sentido, una ''capa'' o recubrimiento físico, aparece en la narración del maná: cuando el rocío que rodeaba el campamento se evaporó, el maná fue hallado bajo ''la capa de rocío'' (Éx 16:13-14). Ambos sentidos derivan de la raíz que significa ''yacer'': lo que yace con alguien o lo que yace sobre el suelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7903', 'spa', 'cohabitación, cópula; emisión seminal en el acto sexual, usado en las leyes levíticas de pureza y santidad', 'Este sustantivo se refiere al acto o emisión de la cópula masculina, y aparece siempre con el verbo «dar» (natán) en contextos de relaciones sexuales prohibidas. Levítico 18:20 y 23 prohíben dar la «emisión» a la mujer del prójimo o a un animal. Levítico 20:15 repite la prohibición con animales. Números 5:20 lo usa en el rito de la sospecha de adulterio: si otro hombre ha «dado su acostamiento» con la mujer. Se trata de vocabulario técnico sacerdotal para la emisión sexual masculina, empleado específicamente en leyes que establecen límites sexuales y pureza ritual. La precisión eufemística refleja la simultaneidad de franqueza y delicadeza con que la Torá trata los asuntos sexuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7908', 'spa', 'privación de hijos, orfandad—el estado de haber perdido hijos', 'Este sustantivo describe la privación de hijos, particularmente la pérdida de niños o estado sin descendencia. Isaías lo usa dos veces (47:8-9) en juicio contra Babilonia, declarando que ella conocerá privación de hijos y viudez. Salmo 35:12 lo emplea para ser despojado o retribuido mal por bien, sugiriendo vacío o pérdida. El término captura pérdida personal profunda, especialmente el duelo de perder descendencia, usado tanto como aflicción literal como metáfora de juicio devastador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7909', 'spa', 'Privado de crías, despojado de hijos; describe a una madre — animal o humana — despojada de sus crías, feroz en su dolor.', 'Adjetivo que describe a quien ha sido despojado de sus crías, con una poderosa carga emocional. Su uso más memorable es el símil de la osa privada de sus cachorros — una madre osa a la que le han arrebatado sus crías se vuelve ferozmente peligrosa (2 S 17:8; Os 13:8; Pr 17:12). Husai advierte a Absalón que los hombres de David son ''feroces como una osa robada de sus crías'', y Proverbios declara que es mejor encontrarse con tal osa que con un necio en su insensatez. En Cantares 4:2 y 6:6, la imagen se suaviza notablemente: ovejas recién lavadas, ''ninguna privada de cría'' — cada oveja con corderos gemelos, estampa de fertilidad y plenitud perfecta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7910', 'spa', 'Borracho, ebrio; usado literalmente de personas vencidas por el vino y figuradamente para referirse a una impotencia tambaleante o al juicio divino. ש', 'Borracho, ebrio; usado literalmente de personas vencidas por el vino y figuradamente para referirse a una impotencia tambaleante o al juicio divino. שִׁכּוֹר es un adjetivo que describe a alguien vencido por el alcohol — tambaleante, aturdido, incapaz de caminar o pensar con claridad. Nabal está literalmente borracho en su banquete (1 S 25:36), y el asesino de Zimri encuentra al rey Ela bebiendo hasta la estupefacción (1 R 16:9). Sin embargo, la palabra posee una poderosa fuerza figurativa: las naciones tambalean como un borracho bajo el juicio de Dios (Is 19:14; 24:20), y el salmista compara a los marineros sacudidos por la tormenta con hombres que se tambalean por el vino (Sal 107:27). Ana es falsamente acusada de ser una mujer borracha (1 S 1:13), una conmovedora lectura errónea de una oración ferviente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7911', 'spa', 'Olvidar, dejar de recordar; pasivo: ser olvidado; causativo: hacer olvidar', 'En su esencia, שָׁכַח capta la dolorosa realidad del fallo de la memoria, ya sea humana o divina. A Israel se le advierte reiteradamente que no olvide el pacto del Señor (Dt 4:9, 23; 6:12; 8:11), mientras que el salmista suplica que Dios no ha olvidado al afligido (Sal 9:12-13; 10:12). El cognado arameo significa «encontrar», un primo semántico irónico, como si lo olvidado en una lengua estuviera simplemente esperando ser hallado en otra. El Nifal pasivo («ser olvidado») da voz a la angustia de quienes se sienten borrados de la memoria (Sal 31:12), mientras que las raras formas causativas describen a Dios o las circunstancias despojando activamente de la memoria (Jer 23:27; Lm 2:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7912', 'spa', 'Arameo: hallar o descubrir (Hafel activo); ser hallado, ser descubierto o salir a la luz (Hitpeel pasivo)', 'Arameo: hallar o descubrir (Hafel activo); ser hallado, ser descubierto o salir a la luz (Hitpeel pasivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7916', 'spa', 'Trabajador asalariado o jornalero; también soldado mercenario; ocasionalmente adjetival para algo alquilado o contratado', 'Trabajador asalariado o jornalero; también soldado mercenario; ocasionalmente adjetival para algo alquilado o contratado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7918', 'spa', 'disminuir, calmarse, aplacarse; dicho de aguas que bajan y de ira que se enfría', 'Verbo que describe la mengua o el apaciguamiento de fuerzas poderosas, ya sean físicas o emocionales. Su uso más vívido aparece en Génesis 8:1, donde Dios hace soplar un viento y las aguas del diluvio disminuyen. En Ester describe cómo la ira del rey se aplaca tras la ejecución de Amán (7:10) y antes de la elección de Ester (2:1). El cognado árabe sakka (''humillarse'') y el sentido posbíblico de ''sosegar la ira'' iluminan la dimensión emocional. El difícil uso en Jeremías 5:26 podría describir a cazadores agazapados o al acecho.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7919a', 'spa', 'Ser prudente, comprender, prosperar o instruir; vincula la percepción cognitiva con su resultado práctico de éxito. שָׂכַל captura una intuición disti', 'Ser prudente, comprender, prosperar o instruir; vincula la percepción cognitiva con su resultado práctico de éxito. שָׂכַל captura una intuición distintivamente hebrea: que la verdadera comprensión y el éxito práctico son inseparables. El mismo verbo que describe entender los caminos de Dios (Sal 14:2) también describe el éxito militar de David (1 S 18:14) y la prosperidad de Josué al meditar en la Torá (Jos 1:8). El árabe separa esto en palabras distintas — fahima para entender, najaha para prosperar — pero el hebreo las mantiene fusionadas. En su forma Hifil causativa, la raíz significa instruir o impartir discernimiento (Sal 32:8), y su participio sustantivado produce el maskil, la persona sabia que tanto capta la verdad como actúa eficazmente conforme a ella. El título sálmico maskil (Sal 47:7) podría referirse a un canto compuesto con destreza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7921a', 'spa', 'Ser privado de hijos, dejar sin hijos o abortar; cubriendo el devastador espectro desde perder hijos nacidos hasta la pérdida del embarazo', 'Ser privado de hijos, dejar sin hijos o abortar; cubriendo el devastador espectro desde perder hijos nacidos hasta la pérdida del embarazo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7922', 'spa', 'Prudencia, discernimiento y entendimiento práctico; raramente astucia o sagacidad usada para fines egoístas', 'Prudencia, discernimiento y entendimiento práctico; raramente astucia o sagacidad usada para fines egoístas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7924', 'spa', 'perspicacia, entendimiento—comprensión penetrante o discernimiento (arameo)', 'Este sustantivo arameo denota perspicacia, entendimiento o discernimiento. Las tres apariciones están en Daniel 5 (versículos 11, 12, 14), describiendo la sabiduría excepcional de Daniel como poseedora de ''perspicacia y entendimiento como la sabiduría de los dioses''. El término aparece en descripciones formulaicas de los dones de Daniel, enfatizando su habilidad para interpretar sueños y resolver misterios. Representa percepción intelectual y espiritual más allá de la capacidad humana ordinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7925', 'spa', 'Levantarse temprano, madrugar (Hifil); usado adverbialmente para indicar acción persistente y diligente; como participio, «madrugador». שָׁכַם es el v', 'Levantarse temprano, madrugar (Hifil); usado adverbialmente para indicar acción persistente y diligente; como participio, «madrugador». שָׁכַם es el verbo bíblico de la iniciativa al amanecer: cargar las bestias de carga y ponerse en marcha antes de la salida del sol. Su forma Hifil aparece prácticamente en cada relato de viaje patriarcal: Abraham «se levantó de mañana» (Gn 22:3), al igual que Jacob (Gn 28:18) y Josué (Jos 3:1). El español madrugar lo captura perfectamente. En la retórica profética, el infinitivo absoluto hashkem se convierte en adverbio de urgencia divina: Dios «madrugando y enviando» profetas (Jer 7:25; 2 Cr 36:15) — un conmovedor giro idiomático que expresa esfuerzo incansable y persistente que el pueblo rechaza. La forma participial en Isaías 5:11 y Oseas 6:4 describe a quienes habitualmente madrugan, ya sea tras la bebida o en una devoción fugaz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7926', 'spa', 'Hombro, la parte del cuerpo usada para cargar pesos; también la ciudad de Siquem, y figuradamente un rechazo obstinado al volverse de espaldas.', 'Hombro, la parte del cuerpo usada para cargar pesos; también la ciudad de Siquem, y figuradamente un rechazo obstinado al volverse de espaldas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7927', 'spa', 'Siquem — la antigua ciudad cananea (actual Nablus) entre los montes Gerizim y Ebal, y el nombre personal del hijo de Hamor. Uno de los topónimos con m', 'Siquem — la antigua ciudad cananea (actual Nablus) entre los montes Gerizim y Ebal, y el nombre personal del hijo de Hamor. Uno de los topónimos con más estratos históricos en las Escrituras. Siquem (actual Nablus) se sitúa en el paso entre el monte Gerizim y el monte Ebal en la serranía central, el primer lugar donde Abram erigió un altar al entrar en Canaán (Gn 12:6). Llegó a ser ciudad de refugio (Jos 20:7), escenario de la renovación del pacto por Josué (Jos 24:1) y el turbulento marco del reinado y destrucción de Abimelec (Jueces 9). El español lo traduce como «Siquem», el francés «Sichem» y el alemán «Sichem», reflejando todos ellos la pronunciación antigua a través de distintos filtros fonológicos. El mismo nombre corresponde al hijo de Hamor el heveo, el príncipe local cuya agresión contra Dina desencadenó la sangrienta represalia de Simeón y Leví (Gn 34).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7928', 'spa', 'Siquem (personal)—individuo del clan manasita que lleva el nombre de la ciudad', 'Este nombre personal identifica a un individuo del linaje de Manasés, distinto de la ciudad más famosa de Siquem aunque lleva el mismo nombre. Números 26:31 y Josué 17:2 lo listan entre los descendientes de Manasés en contextos genealógicos y de herencia de tierra. Primera de Crónicas 7:19 lo incluye en la genealogía de Manasés. La conexión del nombre con la ciudad sugiere una posible relación epónima, donde clan y ubicación compartieron nomenclatura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7931', 'spa', 'Asentarse, habitar, morar; de la presencia de Dios: hacer tabernáculo; causativo: hacer habitar, establecer', 'Un verbo de habitación arraigada que se extiende desde la residencia humana ordinaria hasta el misterio sobrecogedor de la presencia divina. Su uso teológicamente más rico describe la שְׁכִינָה: la gloria de Dios «posándose» sobre el Sinaí (Éx 24:16) y «morando» en el Tabernáculo (Éx 25:8). El cognado arameo שְׁכִינָה (Shejiná) y el árabe سَكَنَ (estar en reposo, habitar) iluminan el significado nuclear de la raíz: no mera localización, sino presencia asentada y reposada. Las formas causativas del Piel y el Hifil extienden el verbo a Dios «haciendo habitar su Nombre» en el santuario elegido (Dt 12:11), un sorprendente giro teológico sin paralelo en ninguna otra religión semítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7934', 'spa', 'Vecino o residente cercano; alguien que habita en proximidad, ya sea un individuo, una nación circundante o un habitante de una ciudad.', 'Vecino o residente cercano; alguien que habita en proximidad, ya sea un individuo, una nación circundante o un habitante de una ciudad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7935', 'spa', 'Secanías/Secanyahu — nombre propio de sacerdotes, levitas y laicos en el Israel postexílico', 'Secanías (que significa ''el SEÑOR ha establecido su morada'') es un nombre teofórico portado por múltiples individuos del período postexílico. El más prominente es un descendiente de Jeconías incluido en la genealogía real de 1 Crónicas 3:21-22, quien posiblemente sea el mismo Secanías de Esdras 8:3, 5. Otro Secanías instó a Esdras a despedir a las esposas extranjeras (Esd 10:2), y el nombre aparece también entre figuras sacerdotales y levíticas en Nehemías y Crónicas. La forma larga שְׁכַנְיָהוּ se encuentra en 1 Crónicas 24:11 y 2 Crónicas 31:15.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7936b', 'spa', 'Contratar o emplear a alguien por un salario; ganar un jornal por el propio trabajo; alquilarse para servicio.', 'Contratar o emplear a alguien por un salario; ganar un jornal por el propio trabajo; alquilarse para servicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7937', 'spa', 'Embriagarse o intoxicarse; causativamente, emborrachar a otro; usado literalmente del vino y figuradamente del juicio divino.', 'Embriagarse o intoxicarse; causativamente, emborrachar a otro; usado literalmente del vino y figuradamente del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7939', 'spa', 'Salario, recompensa o precio de alquiler; pago por trabajo, retribución divina o tarifa por servicios', 'Salario, recompensa o precio de alquiler; pago por trabajo, retribución divina o tarifa por servicios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7941', 'spa', 'Bebida embriagante distinta del vino; bebida fermentada regulada en textos sacerdotales, nazareos y proféticos', 'Bebida embriagante distinta del vino; bebida fermentada regulada en textos sacerdotales, nazareos y proféticos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7943', 'spa', 'embriaguez—estado de intoxicación, literal o metafórico', 'Este sustantivo describe embriaguez, usado exclusivamente en contextos figurativos para juicio divino. Jeremías 13:13 amenaza con llenar a los habitantes de embriaguez (desconcierto bajo juicio). Ezequiel lo usa para una copa de horror y desolación (23:33) y para estar ebrio de sangre (39:19). El término transmite no bebida festiva sino los efectos desorientadores y devastadores de la ira de Dios, donde naciones o pueblos tambalean impotentemente bajo juicio como personas intoxicadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7945', 'spa', 'que, porque—partícula relativa que introduce cláusulas, a menudo causal', 'Esta partícula sirve como conector relativo o causal del hebreo tardío, significando ''que'', ''cual'' o ''porque''. Aparece en varias formas antes de diferentes consonantes, funcionando similarmente al más común אֲשֶׁר. Segunda de Reyes 6:11 la usa causalmente (''a causa de esto''). Eclesiastés 8:17 la emplea como relativo (''lo que''). Jonás 1:12 la tiene en ''por mi causa''. La partícula representa desarrollo lingüístico hacia formas comunes en hebreo mishnaico y arameo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7948', 'spa', 'marcos, rebordes—elementos estructurales que unen partes de las bases del templo', 'Este sustantivo plural se refiere a los marcos, rebordes o uniones de las bases de bronce en el templo de Salomón. Primera de Reyes 7:28-29 describe estos elementos estructurales tres veces, indicando que eran paneles o piezas conectoras entre los componentes de las bases. La característica arquitectónica exacta es debatida—si rebordes, costillas, marcos o elementos de unión—pero claramente servían para unir o bordear secciones de las elaboradas bases con ruedas que sostenían las pilas del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7950', 'spa', 'Nieve — el fenómeno meteorológico y un símil bíblico omnipresente de blancura, pureza y limpieza.', 'Nieve — el fenómeno meteorológico y un símil bíblico omnipresente de blancura, pureza y limpieza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7951', 'spa', 'estar tranquilo, en paz, prosperar; describe tanto la paz genuina como la engañosa seguridad de los impíos', 'Verbo que significa estar en paz, tranquilo o próspero. Porta una llamativa ambigüedad moral: la misma raíz describe la paz anhelada del justo y la inquietante prosperidad del impío. Job lo emplea en ambos sentidos: no tenía reposo ni antes de la calamidad (3:26), pero las tiendas de los salteadores gozan de paz (12:6). Jeremías plantea la clásica pregunta de teodicea: ¿por qué prosperan los malvados? (12:1). Lamentaciones 1:5 señala que los enemigos de Jerusalén prosperan. La oración del salmista por la paz de Jerusalén (Sal 122:6) ofrece el contrapunto redentor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7956', 'spa', 'Sela, el tercer hijo de Judá y su esposa cananea, ancestro de un clan en la tribu de Judá', 'Nombre propio Sela, que designa al tercer hijo de Judá con su esposa cananea Bat-súa. Su historia se entrelaza con la dramática narrativa de Génesis 38: tras la muerte de sus hermanos mayores Er y Onán, Judá retuvo al joven Sela y no lo dio en matrimonio a Tamar, temiendo que también muriera (Gn 38:11, 14, 26). Esta promesa incumplida fue lo que llevó a Tamar a su célebre ardid. Sela sobrevivió y llegó a ser ancestro de un clan registrado en Números 26:20 y 1 Crónicas 2:3; 4:21.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7957', 'spa', 'llama—fuego intenso, especialmente como juicio divino o amor poderoso', 'Este sustantivo femenino denota llama, particularmente fuego intenso o poderoso. Ezequiel 20:47 lo usa para la llama del juicio que consume el sur. Job 15:30 advierte al malvado que la llama destruirá sus ramas. Cantares 8:6 habla de los ''relámpagos de fuego, llama de Yah'' del amor, describiendo la pasión como llama divina. El término enfatiza el poder y la intensidad del fuego, ya sea en juicio, destrucción o la fuerza abrumadora del amor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7958', 'spa', 'Codorniz; aves migratorias pequeñas (coturnix) provistas milagrosamente por Dios como alimento en el desierto', 'Este sustantivo designa a la codorniz, el ave migratoria pequeña que Dios proveyó al pueblo de Israel durante su travesía por el desierto. Éxodo 16:13 describe cómo las codornices cubrieron el campamento al atardecer, acompañadas del maná matutino. Números 11:31-32 narra una provisión aún mayor, pero seguida de una plaga divina contra la avidez desmedida del pueblo. El Salmo 105:40 recuerda esta provisión como acto de la fidelidad de Dios. Las codornices migran efectivamente a través del Sinaí en bandadas enormes, lo cual hace el relato ecológicamente verosímil sin restarle su carácter milagroso. La historia encarna tanto la generosidad divina como el peligro del apetito desenfrenado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7960', 'spa', 'negligencia, descuido, falta en el deber (término administrativo arameo raro)', 'Este sustantivo arameo raro aparece solo en Esdras y Daniel en contextos administrativos advirtiendo contra la negligencia. El término conlleva el sentido de fallar en cumplir una obligación o permitir que algo importante se pase por alto. Las glosas en español e inglés enfatizan consistentemente la idea de falla y negligencia, mientras que la tradición textual muestra cierta incertidumbre (la variación Ketiv-Qere en Daniel 3:29 sugiere posible confusión textual con una raíz similar). Los contextos uniformemente advierten contra el descuido en asuntos de estado o deber religioso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7961', 'spa', 'Tranquilo, en reposo, sosegado; de personas que gozan de seguridad imperturbable, o como sustantivo, un estado de quietud apacible', 'Describe una condicion de calma, seguridad y reposo, aplicable tanto a personas como a naciones o territorios. Job conocio esta palabra de manera dolorosa: habia estado en reposo (Job 16:12) antes de que Dios quebrantara su paz. El salmista observa que los impios estan «tranquilos para siempre» (Sal 73:12), y Jeremias habla de una nacion que habita segura y sin perturbacion (Jer 49:31). En algunos pasajes el adjetivo adquiere un uso sustantivado, denotando «quietud» o «paz» como cualidad de la tierra o del estado interior (1 Cr 4:40; Job 20:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7962', 'spa', 'Quietud, tranquilidad, holgura; abarca desde la genuina seguridad apacible hasta la complacencia descuidada segun el contexto moral', 'Denota un estado de calma y reposo imperturbable, experimentado ya sea como prosperidad genuina o como complacencia peligrosa. En Salmo 122:7 se usa en paralelo con shalom como bendicion sobre Jerusalen, y Proverbios 17:1 elogia un bocado seco disfrutado en quietud por encima de una casa llena de banquetes con contienda. Sin embargo, la misma palabra conlleva una advertencia severa en Proverbios 1:32, donde la «holgura de los necios» los destruye, y en Ezequiel 16:49, donde el pecado de Sodoma incluia «abundancia de ociosidad». El hebreo insiste en que la calidad moral de esa calma depende enteramente de quien la posee.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7964', 'spa', 'regalo de despedida, dote, envío (regalo dado en la separación)', 'Este sustantivo plural denota regalos dados en el momento de la partida o separación. La palabra aparece en dos contextos distintos pero relacionados: despido formal (Moisés enviando a su esposa, Éxodo 18:2) y regalos de dote que acompañan a una novia (Faraón dando Gezer como regalo de bodas, 1 Reyes 9:16). Miqueas extiende la metáfora a la ''despedida'' forzada de Israel a Moreset-gat, representando la pérdida como dar regalos de despedida. Las glosas multilingües (''dowry,'' ''parting gifts,'' ''regalo de despedida'') capturan tanto la transferencia ceremonial de propiedad como el tono emocional de separación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7965', 'spa', 'Plenitud, integridad, bienestar, paz; abarca tranquilidad, bienestar, fórmulas de saludo, alianza interpersonal y totalidad', 'שָׁלוֹם es probablemente la palabra de mayor resonancia cultural en el hebreo bíblico, aunque su significado va mucho más allá de lo que el español «paz» sugiere. Construida sobre la raíz ש-ל-ם, que denota integridad y plenitud, abarca la salud corporal («¿estás bien?»), la seguridad nacional (ausencia de guerra), la armonía relacional (pacto de paz) y funciona incluso como saludo y despedida habituales. El árabe salām conserva el cognado pero lo restringe principalmente a la seguridad y el saludo, mientras que el coreano pyeonghwa capta la dimensión de la tranquilidad y el alemán Friede el cese de conflictos. Ninguna traducción en lengua alguna logra captar plenamente la integridad integrada que שָׁלוֹם vislumbra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7966', 'spa', 'retribución, recompensa, pago (tanto recompensa como castigo)', 'Este sustantivo denota el acto de devolver lo que se debe, ya sea como castigo o recompensa. Aparece en contextos proféticos anunciando juicio divino (Isaías 34:8 lo llama ''el año de retribución para la controversia de Sion,'' paralelo a ''venganza'') y en Oseas 9:7 advirtiendo que ''han llegado los días de la retribución.'' El sentido más oscuro de retribución judicial domina, aunque Miqueas 7:3 cambia a la corrupción humana donde los jueces toman sobornos como su ''recompensa.'' Las glosas en español e inglés (''retribución,'' ''recompense,'' ''bribe'') reflejan esta doble posibilidad de pago legítimo versus recompensa corrupta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7967', 'spa', 'Salum: nombre teofórico que significa ''recompensado/completo,'' llevado por reyes, sacerdotes, levitas y otras figuras', 'Salum: nombre teofórico que significa ''recompensado/completo,'' llevado por reyes, sacerdotes, levitas y otras figuras');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7969', 'spa', 'Tres — el número cardinal, usado de forma independiente, en estado constructo y en numerales compuestos', 'Las formas שָׁלֹשׁ (masculino) y שְׁלֹשָׁה (femenino) suman 431 apariciones del número cardinal tres en la Biblia hebrea. Más allá del conteo simple, el «tres» posee un peso estructural notable en la narrativa bíblica: tres visitantes a Abraham (Gn 18:2), tres días de tinieblas (Éx 10:22), tres divisiones del Salterio. El número aparece en cadenas constructas («tres de ellos»), con prefijos preposicionales («por tres», «desde tres») y en numerales compuestos («trece», «trescientos»). La evidencia interlingüística es completamente uniforme: español «tres», francés «trois», alemán «drei», sin divergencia semántica alguna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7970', 'spa', 'Treinta; también título del cuerpo de élite de guerreros de David («los Treinta»)', 'El número cardinal treinta aparece a lo largo de la Biblia hebrea en edades, medidas, conteos y sumas monetarias, desde los treinta codos del arca de Noé (Gn 6:15) hasta las treinta piezas de plata en la alegoría del pastor de Zacarías (Zac 11:12-13). Más allá del simple cómputo, la palabra adquiere una función cuasi-nominal en las listas militares de 2 Samuel 23 y 1 Crónicas 11-12, donde «los Treinta» designa el cuerpo de élite de David, un rango titulado distinto de la mera enumeración. Todas las grandes tradiciones de traducción emplean el numeral esperado —español «treinta», francés «trente», alemán «dreißig»—, pero el uso sustantivado militar constituye una acepción aparte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7971', 'spa', 'Enviar, despachar; extender (la mano); despedir, soltar; ser enviado; prender fuego; expulsar, echar fuera', 'El verbo שָׁלַח es la palabra principal de la Biblia Hebrea para enviar — mensajeros, cartas, plagas e incluso la mano de Dios. Sus 847 apariciones recorren prácticamente todo arco narrativo desde Génesis hasta Malaquías. En Qal significa enviar o despachar (Gn 8:7-12, la paloma del arca), pero también extender la mano con poder o violencia (Gn 22:10; Éx 3:20). El Piel se intensifica en comisión deliberada (''despedir, soltar, liberar''), gobernando el drama del Éxodo: la negativa del Faraón a ''dejar ir'' (שַׁלַּח) a Israel. Un sentido destructivo poco frecuente — prender fuego a un lugar — y la expulsión forzosa (Gn 3:23, la expulsión del Edén) completan el amplio arco semántico de este verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7972', 'spa', 'Enviar, despachar (arameo); enviar una carta, persona o decreto, o extender la mano. שְׁלַח es el cognado arameo estándar del hebreo שָׁלַח, usado pre', 'Enviar, despachar (arameo); enviar una carta, persona o decreto, o extender la mano. שְׁלַח es el cognado arameo estándar del hebreo שָׁלַח, usado predominantemente en Esdras y Daniel para actos oficiales de envío: despachar cartas, emisarios y decretos reales. La correspondencia burocrática de Esdras 4-5 gira en torno a este verbo: los funcionarios ''enviaron'' informes a Darío, quien ''envió'' respuestas de vuelta. En un caso memorable (Esd 6:12), Darío advierte que Dios derribará a todo rey que ''extienda'' su mano para alterar el decreto del templo, ampliando el significado básico de ''enviar'' al gesto físico de alcanzar para destruir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7973', 'spa', 'Proyectil o arma (jabalina, dardo); tambien brotes o renuevos de una planta', 'Derivado de la raiz shalakh (''enviar''), este sustantivo designa lo que es ''lanzado'' o ''enviado'', ya sea un arma arrojada en batalla o un brote que surge de una planta. Su ambito principal es militar: los constructores de Nehemias sostenian cada uno ''su arma'' mientras trabajaban (Neh 4:17, 23), y los guardias del templo se apostaban con sus ''armas'' en 2 Cronicas 23:10. En Job, el shelakh representa el instrumento letal de muerte (Job 33:18; 36:12). Un hermoso sentido botanico emerge en Cantares 4:13, donde los ''renuevos'' de la amada son un paraiso de granados, transformando ese mismo ''enviar'' en el crecimiento exuberante de un jardin.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7974', 'spa', 'Sala, hijo de Arfaxad y ancestro de Abraham en la genealogía patriarcal desde Sem hasta Abram', 'Nombre propio en la genealogía que conecta a Sem, hijo de Noé, con Abraham, identificando al hijo de Arfaxad y padre de Heber (Gn 10:24; 11:12-15). Sala ocupa una posición clave en la Tabla de las Naciones y en el linaje semita, sirviendo de puente entre el mundo postdiluviano y los hebreos a través de su hijo Heber, de quien posiblemente derive la designación ''hebreo''. El nombre aparece tanto en Génesis como en 1 Crónicas (1:18, 24), y la LXX lo traduce como Σαλα.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7979', 'spa', 'שֻׁלְחָן (shuljan) — mesa para comer, banquetes reales o uso ritual; por metonimia, la provisión dispuesta sobre ella. Este sustantivo masculino abarc', 'שֻׁלְחָן (shuljan) — mesa para comer, banquetes reales o uso ritual; por metonimia, la provisión dispuesta sobre ella. Este sustantivo masculino abarca desde la estera de cuero extendida en el suelo según la práctica semítica antigua hasta el mobiliario elaborado de palacios y templos. Aparece 71 veces en contextos que van desde lo doméstico (Jue 1:7, donde reyes vencidos recogen migajas bajo una mesa), lo regio (la mesa de David, 2 S 9:7-13; la mesa de Salomón, 1 R 10:5), lo sacro (la mesa de los panes de la proposición, Ex 25:23-30) hasta lo metafórico (Sal 23:5, «tú preparas mesa delante de mí»). Por metonimia puede representar la provisión o la comunión asociada al acto de comer. El español mesa, el francés table y el alemán Tisch convergen en un único equivalente, confirmando que el sentido de objeto físico y el de provisión metonímica permanecen léxicamente unidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7980', 'spa', 'Dominar, tener senorio, ejercer autoridad sobre; en Hifil, facultar u otorgar autoridad a otro', 'Verbo hebreo tardio que significa ejercer poder o dominio sobre otros. En Ester 9:1 conlleva una ironia dramatica: el mismo dia en que los enemigos esperaban dominar a los judios, estos se ensenorearon de quienes los odiaban. Eclesiastes lo emplea repetidamente para explorar la amarga ironia de la autoridad humana: uno domina sobre otro para su propio dano (8:9), y quien labora con sabiduria puede ver su riqueza dominada por un necio (2:19). El Hifil causativo anade la dimension de Dios otorgando o reteniendo el poder para disfrutar de lo que uno posee (Ec 5:19; 6:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7981', 'spa', 'Tener poder o dominio, gobernar; en Hifil, designar a alguien como gobernante (arameo שְׁלֵט)', 'Verbo arameo que aparece exclusivamente en Daniel, abarcando desde tener poder bruto sobre fuerzas fisicas hasta ejercer dominio real. En Daniel 3:27 el fuego ''no tuvo poder'' sobre los tres jovenes, mientras que en 5:7 y 5:16 el verbo describe ser designado gobernante del reino. La forma causativa Hifil capta la autoridad otorgada por Dios a Nabucodonosor para conceder gobierno a otros (Dan 2:38, 2:48). La distincion entre el poder fisico directo y la autoridad politica delegada muestra la amplitud semantica de esta raiz en el contexto de la soberania divina sobre los reinos humanos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7982', 'spa', 'escudo, broquel — tipo de armamento defensivo, a menudo ornamental, colgado en muros o llevado en batalla', 'שֶׁלֶט (shelet) designa un tipo particular de escudo o broquel cuya forma exacta sigue siendo debatida entre los estudiosos. Algunas versiones antiguas sugieren ''carcajes'' o ''equipo'', pero la lectura predominante en las traducciones es la de un escudo defensivo. David capturó שְׁלָטִים de oro de los siervos de Hadad-ezer (2 Sam 8:7), y el Templo de Salomón exhibió tales escudos como trofeos. En Cantares 4:4 cuelgan decorativamente en una torre junto a los מָגִנִּים, lo que sugiere que שֶׁלֶט pudo haber sido un tipo más pequeño y ornamental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7985', 'spa', 'Dominio, autoridad soberana; término arameo para el poder de gobernar, especialmente el reinado eterno de Dios en Daniel. Sustantivo arameo usado excl', 'Dominio, autoridad soberana; término arameo para el poder de gobernar, especialmente el reinado eterno de Dios en Daniel. Sustantivo arameo usado exclusivamente en Daniel para designar el dominio soberano y la autoridad de gobierno. Describe tanto la realeza humana como la divina, pero su peso teológico recae abrumadoramente sobre el reinado eterno de Dios: ''Su dominio es dominio eterno que no pasará'' (Dn 7:14). La palabra aparece en las doxologías de Nabucodonosor reconociendo la soberanía divina tras experiencias de humillación (Dn 4:3, 34) y en el decreto de Darío ordenando que todos tiemblen ante el Dios de Daniel, ''cuyo dominio perdurará hasta el fin'' (Dn 6:26). Daniel 7 la emplea repetidamente para contrastar el dominio temporal de los imperios bestiales con el dominio eterno dado al Hijo del Hombre y a los santos del Altísimo (Dn 7:6, 12, 14, 26–27).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7989', 'spa', 'Gobernante, señor; persona con dominio o autoridad, ya sea legítima o despótica', 'Este adjetivo sustantivado describe a quien posee dominio o autoridad para gobernar. En Génesis 42:6 se aplica a José como «el gobernante de la tierra» de Egipto. Eclesiastés lo emplea tres veces: 7:19 habla de gobernantes en una ciudad, 8:8 observa que nadie tiene dominio sobre el viento ni sobre el día de la muerte, y 10:5 menciona un error que procede «del gobernante». El uso en Eclesiastés es particularmente matizado: los gobernantes tienen poder, pero las realidades últimas —la muerte, las fuerzas naturales— escapan a todo dominio humano. El término puede tener connotaciones neutras o negativas según el contexto, desde la gobernanza legítima hasta el control autoritario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7990', 'spa', 'Que gobierna, que domina; como adjetivo: que ejerce autoridad; como sustantivo: gobernante, capitán; también permitido, autorizado', 'Adjetivo arameo que describe a quien posee dominio o ejerce poder de gobierno. En Daniel caracteriza a Dios como aquel que gobierna sobre los reinos humanos (Dn 4:17, 25) y designa a funcionarios como capitanes y gobernantes (Dn 2:10, 15). La palabra posee un segundo matiz diferenciado en Esdras 7:24, donde pasa de la autoridad política al permiso legal: ''no está autorizado'' imponer tributo. Las glosas en español como ''domina/dominan'' reflejan consistentemente el sentido de poder de gobierno, mientras que el pasaje de Esdras se distingue como una construcción impersonal de legalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7991c', 'spa', 'Oficial militar: originalmente el ''tercer hombre'' en un carro de guerra; una tríada o grupo de tres; el numeral treinta.', 'Oficial militar: originalmente el ''tercer hombre'' en un carro de guerra; una tríada o grupo de tres; el numeral treinta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7992', 'spa', 'Tercero (ordinal); también tercera parte, de tres años o tercer piso — el adjetivo ordinal con extensiones fraccionales y especializadas', 'El número ordinal «tercero» en hebreo, שְׁלִישִׁי, es mucho más versátil que un simple vocablo de secuencia. Su uso más frecuente marca orden: el tercer día, el tercer año, el tercer hijo, apareciendo en el relato de la creación (Gn 1:13), las historias patriarcales y los libros históricos. Pero también funciona como sustantivo fraccional («la tercera parte»), dividiendo ejércitos (2 S 18:2) y juicios proféticos (Ez 5:2, 12) en tercios. Dos extensiones especializadas completan su alcance: la descripción de animales sacrificiales como «de tres años» (Is 15:5; Jr 48:34) y la identificación del «tercer piso» del templo de Ezequiel (Ez 42:3). El español refleja la escisión ordinal/fraccional con «tercero» y «tercio»; el alemán usa «dritte» y «Drittel».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7993', 'spa', 'Arrojar, lanzar, echar (Hifil); ser arrojado (Hofal); figuradamente, desechar o rechazar', 'שָׁלַךְ es el verbo hebreo más enérgico para la acción de arrojar, y aparece siempre en el Hifil causativo o su contraparte pasiva, el Hofal, nunca en el Qal simple. La palabra conlleva una violencia o determinación inherente que la distingue de términos más suaves como שָׁלַח («enviar») o נָתַן («dar, poner»). Cuando Moisés arroja su vara al suelo y se convierte en serpiente (Éx 4:3), cuando los marineros lanzan la carga por la borda en la tempestad (Jon 1:5), cuando Dios amenaza con echar a Israel de su presencia haciendo que el exilio se sienta físico (2 R 24:20), siempre emplea este verbo. Su espectro va desde el lanzamiento concreto de objetos al agua, al fuego o a fosas, pasando por el derribo violento en el juicio, hasta el desecho metafórico de pecados, ídolos y obligaciones pactuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7997b', 'spa', 'Saquear, despojar; despojar a alguien de sus posesiones por la fuerza, o ser despojado y convertido en presa. Verbo de despojo violento, frecuentement', 'Saquear, despojar; despojar a alguien de sus posesiones por la fuerza, o ser despojado y convertido en presa. Verbo de despojo violento, frecuentemente emparejado con bazaz (''tomar como botín'') para describir el despojo de riquezas de pueblos y ciudades conquistados. Las profecías de Ezequiel contra Tiro (26:12) y Egipto (29:19) lo emplean para el saqueo total de tesoros nacionales. Habacuc 2:8 invierte la situación: ''porque tú has saqueado a muchas naciones, todos los pueblos restantes te saquearán a ti''. El Hitpael reflexivo-pasivo aparece en dos pasajes notables —Salmo 76:5 (guerreros ''despojados'' de su botín) e Isaías 59:15 (el justo ''convertido en presa'')— desplazando el enfoque del agresor a la víctima.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7998', 'spa', 'Botín, despojo o presa — bienes tomados por la fuerza en la guerra, incluyendo ganado, vestiduras, metales preciosos y cautivos. שָׁלָל es el término ', 'Botín, despojo o presa — bienes tomados por la fuerza en la guerra, incluyendo ganado, vestiduras, metales preciosos y cautivos. שָׁלָל es el término principal de la Biblia hebrea para designar los frutos materiales de la victoria militar: todo lo que se despoja de un enemigo vencido o de una ciudad capturada. Abarca vestiduras y oro (Jos 7:21), rebaños y manadas (1 S 30:20), telas y mujeres (Jue 5:30), e incluso poblaciones enteras tomadas como cautivas (Dt 20:14). La palabra aparece en algunos de los pasajes más vívidos de las Escrituras: Benjamín devorando la presa como un lobo y repartiendo el botín (Gn 49:27), y el nombre profético Maher-shalal-hash-baz («rápido es el botín», Is 8:1-3), que convierte el despojo en signo escatológico. El español botín, el francés butin y el alemán Beute convergen en «botín de guerra», sin que surja un sentido secundario en las distintas lenguas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7999a', 'spa', 'Estar completo, estar en paz; pagar, retribuir; cumplir votos; restituir; llevar a término', 'De la misma raíz que da origen a שָׁלוֹם, este verbo porta el significado fundamental de integridad y plenitud. En el Qal describe un estado de completitud o conclusión. El Piel —con diferencia la conjugación más frecuente— desplaza el sentido hacia hacer completa una cosa en sentido transaccional: pagar lo debido, cumplir un voto o restituir lo perdido. El Hifil lo extiende hacia la causación de la completitud, y el Pual provee la contraparte pasiva. Ya sea describiendo la terminación del templo de Salomón (1 R 7:51), el cumplimiento de un voto a Dios (Sal 50:14) o la restitución de bienes robados (Éx 22:1), el hilo conductor es siempre la restauración de la integridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H7999b', 'spa', 'Estar en paz, hacer paz, cumplir o estar completamente consagrado; de la raíz שׁלם que expresa plenitud, integridad y armonía de pacto. Este verbo den', 'Estar en paz, hacer paz, cumplir o estar completamente consagrado; de la raíz שׁלם que expresa plenitud, integridad y armonía de pacto. Este verbo denominativo se nutre del rico campo semántico de שׁלם —integridad, plenitud, paz. En su forma Hifil, significa principalmente hacer paz con otra parte, como cuando los gabaonitas hicieron paz con Israel (Jos 10:1, 4) o cuando Josafat estaba en paz con el rey de Israel (1 R 22:44). El Qal transmite un sentido estativo de estar en paz o en amistad de pacto, como en Job 22:21 (''reconcíliate con él'') y Salmo 7:4 (''el que estaba en paz conmigo''). Un matiz distinto del Hifil aparece en Isaías 44:26, donde Dios ''cumple'' o lleva a su término la palabra de su siervo. El participio Pual en Isaías 42:19 describe a alguien consagrado o íntegro —el ''perfecto''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8000', 'spa', 'completar, terminar, entregar en su totalidad (término administrativo/teológico arameo)', 'Este verbo arameo lleva el sentido básico de llevar algo a su conclusión o medida completa. En Esdras 5:16 describe el templo siendo ''terminado'' (participio pasivo). Esdras 7:19 usa la forma causativa: ''entrega en su totalidad'' los utensilios del templo a Dios. De manera más dramática, Daniel 5:26 anuncia el veredicto de Dios sobre Belsasar: ''Dios ha contado tu reino y lo ha terminado''—lo ha llevado a su fin divinamente designado. La raíz se conecta con la familia semítica más amplia de palabras sobre totalidad y conclusión, pero aquí enfatiza la conclusión definitiva o entrega completa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8001', 'spa', 'bienestar, prosperidad, paz (fórmula de saludo aramea)', 'Este sustantivo arameo funciona como una fórmula de saludo estándar en la correspondencia oficial del período persa y en decretos reales. Aparece en la apertura o cierre de cartas deseando bienestar y prosperidad al destinatario. Esdras 4:17 lo usa de manera absoluta: ''¡Paz!'' El uso en Daniel es más completo: ''Que tu paz se multiplique en gran manera'' (3:31, 6:26). El término es el cognado arameo del hebreo shalom, con matices similares de bienestar integral, seguridad y prosperidad. La evidencia multilingüe (''paz,'' ''peace,'' ''prospérité'') confirma este sentido de bienestar holístico en lugar de mera ausencia de conflicto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8002', 'spa', 'Ofrenda de paz — una comida sacrificial compartida que expresa comunión, gratitud o cumplimiento de un voto ante Dios. El שֶׁלֶם (shelamim, «ofrenda d', 'Ofrenda de paz — una comida sacrificial compartida que expresa comunión, gratitud o cumplimiento de un voto ante Dios. El שֶׁלֶם (shelamim, «ofrenda de paz») designa un sacrificio israelita distintivo en el que la carne se compartía entre Dios, el sacerdote y el adorador, haciéndolo singularmente comunitario. A diferencia del holocausto consumido enteramente sobre el altar, la ofrenda de paz creaba una comida de comunión. Podía ofrecerse en acción de gracias, para cumplir un voto o como expresión voluntaria de devoción (Lv 3:1-17; 7:11-21). La Septuaginta lo traduce de diversas formas como εἰρηνική («relativo a la paz») y σωτήριον («ofrenda de salvación»), reflejando el antiguo debate sobre su fuerza precisa. El francés sacrifice de paix y el alemán Friedensopfer captan la dimensión de «paz/bienestar». El término aparece prominentemente en Levítico pero también en momentos narrativos cruciales como el incidente del becerro de oro (Ex 32:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8003', 'spa', 'Completo, entero, sano o pacífico; plenitud de medida, integridad moral, seguridad física o intención amistosa', 'Completo, entero, sano o pacífico; plenitud de medida, integridad moral, seguridad física o intención amistosa');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8007', 'spa', 'Salma, Salmón; nombre propio del padre de Booz en la genealogía de David y la línea mesiánica', 'Este es el nombre de un antepasado importante en la genealogía davídica: el padre de Booz (esposo de Rut) y bisabuelo del rey David. El nombre aparece con variantes ortográficas: Salmón (Rut 4:21) y Salma (Rut 4:20, 1 Crónicas 2:11), reflejando distintas tradiciones textuales o diferencias de pronunciación. En 1 Crónicas 2:51, 54 se menciona además a un Salma como «padre de Belén», lo que probablemente indica la vinculación del clan con esa ciudad. Como antepasado de David y, por tanto, de Jesús en las genealogías del Nuevo Testamento, Salma/Salmón posee un significado teológico que trasciende su identidad individual: es un eslabón en la cadena de la promesa desde Judá, a través de Rut, hasta la línea real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8008', 'spa', 'Vestidura, manto exterior — una prenda grande o capa usada sobre el cuerpo para cubrirse y abrigarse.', 'Vestidura, manto exterior — una prenda grande o capa usada sobre el cuerpo para cubrirse y abrigarse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8010', 'spa', 'Salomón — hijo de David, rey de Israel célebre por su sabiduría, riqueza y la construcción del Templo', 'שְׁלֹמֹה es el nombre propio del tercer rey de Israel, con 293 apariciones en Samuel, Reyes, Crónicas, Esdras-Nehemías y el Cantar de los Cantares. El nombre deriva de שָׁלוֹם («paz»), en consonancia con un reinado marcado por la ausencia de guerra y la edificación del Primer Templo. Es presentado como hijo de David y Betsabé (2 S 12:24), designado sucesor antes de la muerte de David (1 R 1:30) y recordado tanto por su extraordinaria sabiduría (1 R 3:12) como por su eventual apostasía (1 R 11:1-8). Las formas española «Salomón», francesa «Salomon» y alemana «Salomo» derivan todas de la forma griega de la Septuaginta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8013', 'spa', 'Selomot / Selomit — nombres propios de figuras levíticas y un hijo de Roboam, con variantes masculina y femenina', 'Nombre propio que aparece en dos formas estrechamente relacionadas en Crónicas y Esdras. Selomot (שְׁלֹמוֹת), la forma masculina, designa a varios levitas en las listas administrativas del templo de 1 Crónicas 23-26, incluido un custodio de los tesoros consagrados. Selomit (שְׁלֹמִית), una variante femenina o de grafía alternativa, aparece en pasajes paralelos y también designa a un hijo de Roboam en 2 Crónicas 11:20 y a un jefe de familia postexílico en Esdras 8:10. Las formas griegas Σαλωμωθ y Σαλωμιθ de la LXX preservan la distinción entre ambas variantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8017', 'spa', 'Selumiel; líder simeonita durante el período del desierto, hijo de Zurisadai', 'Nombre propio masculino que significa ''Dios es mi paz'' o ''amigo de Dios'', llevado por el jefe de la tribu de Simeón durante la peregrinación por el desierto. Selumiel hijo de Zurisadai aparece en el censo (Nm 1:6), la disposición del campamento (2:12), las ofrendas de dedicación del tabernáculo (7:36, 41) y la partida desde el Sinaí (10:19). La LXX lo transcribe como Σαλαμιηλ. Como muchos nombres israelitas compuestos con El, expresa confianza en la amistad protectora de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8018', 'spa', 'Selemías/Shelemyahu — nombre propio de porteros, oficiales y otros en tiempos de Jeremías y la era postexílica', 'Selemías (que significa ''el SEÑOR ha retribuido/completado'') identifica a varios individuos en los libros de Jeremías, Esdras, Nehemías y Crónicas. Durante el ministerio de Jeremías aparecen múltiples hombres con este nombre: el padre de Jehudí (Jer 36:14), uno enviado a arrestar a Jeremías (Jer 36:26) y un centinela que detuvo al profeta en la puerta de Benjamín (Jer 37:13). Un portero levítico con este nombre sirvió en tiempos de David (1 Cr 26:14), identificado como la misma persona llamada Salum en otros pasajes. Entre los portadores postexílicos se cuentan constructores del muro y un tesorero sacerdotal en Nehemías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8019a', 'spa', 'Selomit, Selomot; nombre propio de varios levitas y un descendiente real, que significa quizá «pacífico» o «íntegro»', 'Este nombre (que aparece en formas masculinas y femeninas: Selomit, Selomot) identifica a varias personas en Crónicas y Esdras, la mayoría levitas. En 1 Crónicas 23:18 y 26:28 se mencionan levitas llamados Selomit involucrados en el servicio del templo. 2 Crónicas 11:20 nombra a una Selomit como hija de Roboam. Esdras 8:10 lista a un Selomit como cabeza de una familia postexílica. El nombre probablemente deriva de שָׁלוֹם (paz, integridad), sugiriendo significados como «el pacífico» o «mi paz». Su frecuencia entre familias levíticas puede reflejar lo apropiado de un nombre asociado a la paz para quienes servían en la casa de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8025', 'spa', 'Sacar o desenvainar (una espada); quitar (una sandalia); extraer o arrancar', 'Sacar o desenvainar (una espada); quitar (una sandalia); extraer o arrancar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8027', 'spa', 'Hacer por tercera vez, dividir en tres partes; de tres años; triple/de tres pisos; al tercer día — denominativo de ''tres''', 'Verbo denominativo construido sobre el numeral שָׁלוֹשׁ (tres), que muestra cómo el hebreo convierte números en verbos activos. Puede significar realizar una acción por tercera vez, como cuando Elías ordena que se vierta agua sobre el altar una tercera vez (1 R 18:34), o dividir un territorio en tres partes (Dt 19:3). Como participio Pual, describe animales sacrificiales de tres años de edad, la edad de madurez para la ceremonia de ratificación del pacto en Gn 15:9. El sentido arquitectónico de ''de tres pisos'' aparece en Ez 42:6, mientras que Ec 4:12 emplea el ''cordón triple'' como proverbio de fortaleza en la unidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8029', 'spa', 'Tercera generación; los descendientes en tercer grado, es decir, nietos o bisnietos', 'Adjetivo ordinal derivado del número tres, empleado sustantivamente para designar a ''los de la tercera generación''. Aparece en la solemne advertencia de que Dios visita la iniquidad de los padres sobre los hijos hasta la tercera y cuarta generación (Éx 20:5; 34:7; Nm 14:18; Dt 5:9). Como tierno contrapunto, Gn 50:23 registra que José vio a los hijos de Efraín ''de la tercera generación'' — sus bisnietos — nacer sobre sus rodillas. La palabra abarca así tanto el juicio como la bendición a lo largo del tiempo generacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8032', 'spa', 'Anteayer; idiomáticamente ''anteriormente, previamente, en el pasado'' (siempre en la frase temol shilshom)', 'Anteayer; idiomáticamente ''anteriormente, previamente, en el pasado'' (siempre en la frase temol shilshom)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8033', 'spa', 'שָׁם -- allí, allá; adverbio locativo que señala un lugar previamente mencionado o implícito en el discurso', 'El adverbio שָׁם (''allí'') es el deíctico locativo estándar del hebreo, que señala un lugar ya establecido en el discurso. Con 835 apariciones abarca toda la Biblia hebrea, desde ''allí puso al hombre que había formado'' (Gn 2:8) hasta oráculos proféticos y poesía sapiencial. Puede indicar ubicación estática (''allí'') o dirección de movimiento (''allá''), y frecuentemente aparece en posición enfática antepuesta para lograr efecto retórico (Miq 4:10; Sal 104:26). Combinado con כִּי (''porque allí...'') o גַּם (''aun allí...''), construye sofisticadas relaciones espaciales y lógicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8034', 'spa', 'Nombre, designación; por extensión fama, reputación o renombre: la palabra por la cual alguien es conocido o recordado', 'Una de las palabras con mayor carga teológica de las Escrituras, שֵׁם designa el nombre por el cual se identifica e invoca a una persona, lugar o divinidad. Cuando Dios revela su שֵׁם a Moisés (Éx 3:15), es mucho más que una etiqueta: porta su carácter, autoridad y compromiso de pacto. Los cognados semíticos confirman una raíz vinculada a la marca de identidad. En un sentido secundario pero poderoso, שֵׁם significa fama o renombre: los ''hombres de שֵׁם'' en Gn 6:4 son guerreros de reputación legendaria, y el שֵׁם de Salomón se extendió a naciones lejanas (1 R 4:31).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8035', 'spa', 'Sem; hijo primogénito de Noé, ancestro de los pueblos semíticos y antepasado del linaje de Abraham.', 'Sem; hijo primogénito de Noé, ancestro de los pueblos semíticos y antepasado del linaje de Abraham.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8036', 'spa', 'Nombre — sustantivo arameo para el nombre de una persona, de una deidad, o una designación de identidad y autoridad', 'El sustantivo arameo שֻׁם (shum), cognado del hebreo שֵׁם, significa «nombre»: identidad personal, reputación o autoridad divina invocada. En Esdras aparece en contextos administrativos persas: los profetas profetizan «en el nombre del Dios de Israel» (Esd 5:1), los oficiales preguntan «¿Cuáles son los nombres de los hombres que edifican esta casa?» (Esd 5:4, 10), y un utensilio se identifica por su nombre (Esd 5:14). En Daniel adquiere peso teológico: Daniel bendice a Dios diciendo «sea bendito el nombre de Dios por los siglos» (Dn 2:20), y Nabucodonosor se dirige a Daniel por su nombre babilónico (Dn 2:26; 4:5).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8040', 'spa', 'El lado izquierdo o la mano izquierda; ocasionalmente denota el norte (al orientarse hacia el este). Cognado del árabe shimal (que significa tanto «iz', 'El lado izquierdo o la mano izquierda; ocasionalmente denota el norte (al orientarse hacia el este). Cognado del árabe shimal (que significa tanto «izquierdo» como «viento del norte»), este sustantivo hebreo designa el lado izquierdo, la dirección izquierda o la mano izquierda. Aparece frecuentemente en pares formulaicos con «derecha» (יָמִין), especialmente en instrucciones de no desviarse «ni a la derecha ni a la izquierda» (Jos 1:7). Cuando los antiguos israelitas se orientaban mirando hacia el este, la mano izquierda correspondía al norte, un uso geográfico conservado en Job 23:9. El español izquierda y el alemán Linke siguen consistentemente su significado direccional en las traducciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8041', 'spa', 'Ir a la izquierda, girar hacia la izquierda; también usar la mano izquierda, como denominativo de ''izquierda''', 'Verbo denominativo del sustantivo שְׂמֹאל (''izquierda''), que significa ir hacia la izquierda, girar a la izquierda o usar la mano izquierda. Siempre aparece en contraste con su opuesto ''ir a la derecha'' (יָמִין). Abraham ofrece a Lot elegir dirección al separarse (Gn 13:9). Isaías 30:21 promete guía divina: ''ya sea que gires a la derecha o a la izquierda''. Ezequiel 21:21 ordena a la espada golpear hacia la izquierda. Los guerreros de 1 Cr 12:2 son benjaminitas ambidiestros que podían ''usar la mano izquierda'' con hondas y arcos, una notable ventaja militar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8042', 'spa', 'Izquierdo, del lado izquierdo; adjetivo que denota la mano izquierda o la dirección espacial izquierda en oposición a la derecha.', 'Adjetivo que significa ''izquierdo'' o ''del lado izquierdo'', usado consistentemente en oposición a יְמָנִי (derecho). Aparece en contextos rituales: la palma izquierda del sacerdote recibe aceite durante la ceremonia de purificación (Lv 14:15-16, 26-27). También se emplea en descripciones arquitectónicas del templo, identificando la columna izquierda (1 R 7:21; 2 Cr 3:17) y el lado izquierdo de la formación de la guardia del templo (2 R 11:11; 2 Cr 23:10). El español distingue el género gramatical con ''el izquierdo'' / ''la izquierda'', reflejando la inflexión masculino/femenino del hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8045', 'spa', 'Destruir o exterminar (Hifil); ser destruido o perecer (Nifal) — aniquilación total de pueblos, naciones o cosas. Un verbo de finalidad devastadora en', 'Destruir o exterminar (Hifil); ser destruido o perecer (Nifal) — aniquilación total de pueblos, naciones o cosas. Un verbo de finalidad devastadora en la Biblia hebrea que transmite aniquilación absoluta. En su forma Hifil (causativa) describe destrucción deliberada por un agente poderoso: Dios destruyendo naciones (Dt 2:22-23), Israel con la orden de aniquilar a los pueblos cananeos (Dt 7:23-24) o Nabucodonosor asolando reinos. En el Nifal (pasivo), el sujeto sufre esa misma ruina total: «ciertamente seréis destruidos» resuena a lo largo de las advertencias del pacto en Deuteronomio (4:26, 28:20). El francés emplea consistentemente détruire/exterminer mientras que el español utiliza destruir, captando ambos la fuerza implacable de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8047', 'spa', 'Desolacion, devastacion u horror; un lugar arruinado o un objeto que provoca espanto', 'Desolacion, devastacion u horror; un lugar arruinado o un objeto que provoca espanto');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8048', 'spa', 'Sama — nombre personal portado por varios hombres, incluido un hijo de Isaí y un jefe edomita', 'Sama (en hebreo שַׁמָּה, posiblemente con el significado de ''desolación'' o ''asombro'') identifica al menos a tres individuos distintos en la Biblia hebrea. Un jefe edomita descendiente de Esaú a través de Reuel aparece en Génesis 36:13, 17 y 1 Crónicas 1:37. De manera más prominente, Sama fue el tercer hijo de Isaí y hermano de David, presente en la escena de la unción en 1 Samuel 16:9 y nuevamente en el campamento israelita frente a Goliat (1 Sam 17:13). Un tercer Sama figura entre los valientes de David (2 Sam 23:11, 25, 33). El nombre es notablemente estable en las traducciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8050', 'spa', 'Samuel — profeta, sacerdote y último juez de Israel que ungió a Saúl y a David como reyes', 'שְׁמוּאֵל es un nombre teofórico popularmente vinculado con el verbo שָׁאַל («pedir»), reflejando la oración de Ana: «lo pedí al Señor» (1 S 1:20). Sus 140 apariciones designan abrumadoramente al profeta que sirvió de puente en la transición de Israel del período de los jueces a la monarquía. Consagrado al servicio del templo desde niño (1 S 1:24-28), Samuel creció hasta convertirse en la autoridad espiritual de la nación: escuchó la voz de Dios en Siló (1 S 3:4-10), lideró el arrepentimiento de Israel en Mizpa (1 S 7:5-6) y ungió, primero a Saúl con reticencia (1 S 10:1) y después a David (1 S 16:13). Incluso tras su muerte, su estatura perdura: Jeremías lo empareja con Moisés como intercesor (Jr 15:1) y el Salmo 99:6 lo cuenta entre quienes invocaron al Señor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8051', 'spa', 'Samúa; nombre propio masculino que significa ''oído'' o ''renombrado'', llevado por tres hombres distintos en las Escrituras', 'Nombre propio masculino que significa ''oído'' o ''renombrado'', derivado de la raíz שָׁמַע (''oír''). Lo llevan al menos tres individuos: un espía rubenita enviado a explorar Canaán (Nm 13:4), un hijo de David nacido en Jerusalén (2 S 5:14; 1 Cr 14:4) y un levita de la comunidad postexílica (Neh 11:17; 12:18). La LXX ofrece diversas transliteraciones — Σαμουηλ, Σαμμους, Σαμουει — reflejando incertidumbre sobre el equivalente griego exacto. La raíz del nombre en ''oír'' lo vincula a la familia más amplia de nombres teofóricos que expresan la atención de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8052', 'spa', 'Informe, noticia, nuevas — lo que se oye y circula; un mensaje profético o renombre', 'Informe, noticia, nuevas — lo que se oye y circula; un mensaje profético o renombre');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8055', 'spa', 'Alegrarse, regocijarse; en Piel, alegrar o causar gozo; término emocional fundamental que abarca celebración festiva, gozo espiritual y deleite divino', 'שָׂמַח es el verbo de gozo más frecuente y directo de la Biblia hebrea. A diferencia de sus cuasi-sinónimos —גִּיל (alegría exultante, danzante), רָנַן (grito jubiloso), שׂוּשׂ (deleite exuberante)— שָׂמַח cubre el terreno emocional más amplio, desde el corazón alegre de quien bebe vino en una fiesta (Dt 14:26) hasta el regocijo cósmico de cielos y tierra ante Yahvé (Sal 96:11-12). La conjugación Piel añade una dimensión causativa: el vino «alegra» el corazón del hombre (Sal 104:15), y el esposo debe «alegrar» a su nueva esposa durante un año entero (Dt 24:5). Interlingüísticamente la palabra se traduce con notable consistencia: árabe فَرِحَ, español «alegrarse», coreano 기뻐하다, suajili -furahi, todas seleccionando el vocabulario de gozo más general y no marcado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8056', 'spa', 'Alegre, gozoso, contento — que describe un estado de gozo; como sustantivo, el que se regocija.', 'Alegre, gozoso, contento — que describe un estado de gozo; como sustantivo, el que se regocija.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8057', 'spa', 'Gozo, alegría o regocijo; abarcando desde la celebración sagrada ante Dios hasta el placer evaluado como aspiración humana. שִׂמְחָה es el sustantivo ', 'Gozo, alegría o regocijo; abarcando desde la celebración sagrada ante Dios hasta el placer evaluado como aspiración humana. שִׂמְחָה es el sustantivo principal de la Biblia hebrea para designar el gozo y la alegría, apareciendo en contextos tan diversos como fiestas de cosecha, coronaciones reales y deleite personal íntimo. Labán reprende a Jacob por haberse ido sin la «alegría» de música y celebración (Gn 31:27), el pueblo se regocija con gran שִׂמְחָה en la unción de Salomón (1 R 1:40) y el salmista declara que en la presencia de Dios hay «plenitud de gozo» (Sal 16:11). En Eclesiastés, sin embargo, שִׂמְחָה adquiere un tono más indagador: Qohélet examina el «placer» (שִׂמְחָה) como posible meta de vida y lo encuentra insuficiente (Ec 2:1-2). El español alegría, el francés joie y el alemán Freude abarcan este rango desde la alegría sagrada hasta el placer examinado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8058', 'spa', 'Soltar, remitir o arrojar; abarca la remisión sabática de deudas, el lanzamiento violento y el tropiezo.', 'En su raíz, este verbo significa ''dejar caer'' o ''soltar'', pero sus aplicaciones se despliegan de forma notable. En la legislación del año sabático (Éx 23:11; Dt 15:2-3) denota la remisión de deudas y el barbecho de la tierra — el español ''soltarás'' y ''remitirá'' reflejan el acto de renunciar a un reclamo financiero. En la violenta narrativa de 2 R 9:33, Jehú ordena ''¡tiradla!'' y Jezabel es arrojada desde la ventana. La palabra también describe a los bueyes tropezando junto a la era (2 S 6:6; 1 Cr 13:9), y en su forma pasiva Nifal los malvados ''son despeñados'' en Sal 141:6.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8059', 'spa', 'Remisión, condonación; la cancelación de deudas prescrita para cada séptimo año', 'En la legislación económica del antiguo Israel, este sustantivo designa la liberación formal o remisión de deudas al final de cada ciclo de siete años. Deuteronomio 15:1-2 introduce el concepto como una suspensión divinamente mandada de las obligaciones financieras entre israelitas, y Deuteronomio 31:10 lo vincula a la lectura pública de la Torá durante la Fiesta de los Tabernáculos. El español ''remisión'' y el inglés ''release'' capturan la fuerza jurídica de este término, que concibe la misericordia económica entretejida en el ritmo de la vida comunitaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8060', 'spa', 'Samay — nombre personal en la tribu de Judá, llevado por tres hombres en las genealogías del Cronista.', 'Nombre propio masculino que designa a tres individuos distintos en las genealogías de Judá registradas en 1 Crónicas. El primer Samay es hijo de Onam y hermano de Jadá (1 Cr 2:28, 32); el segundo es hijo de Requem en una línea calebita (1 Cr 2:44-45); y el tercero aparece como hijo de Mered en un sub-clan judaíta (1 Cr 4:17). La LXX transcribe el nombre de diversas formas: Sammai, Sammei y Sami. La glosa alemana ''mein Name'' parece ser una lectura etimológica que lo conecta con la raíz ''shem'' (nombre). Todas las ocurrencias se limitan a los registros tribales del Cronista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8061', 'spa', 'Semida (nombre personal: descendiente de Manasés)', 'Semida fue un líder de clan dentro de la tribu de Manasés, mencionado en registros genealógicos y listas de distribución de tierras. El nombre puede significar ''el nombre conoce'' según algunos estudiosos, comparando paralelos sabeos. Aparece en el censo de las familias de Israel (Números 26:32) y en la distribución del territorio cananeo a su clan (Josué 17:2), luego nuevamente en la genealogía del Cronista (1 Crónicas 7:19). Las traducciones griegas muestran variación consonántica típica (Symear, Samareim, Sameida), reflejando los desafíos de transliterar nombres hebreos al griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8064', 'spa', 'Cielos, cielo; la bóveda visible sobre la tierra, morada de Dios, la esfera cósmica de estrellas y fenómenos atmosféricos', 'שָׁמַיִם aparece en la primera página de la Biblia —«En el principio creó Dios los cielos y la tierra» (Gn 1:1)— y sigue siendo uno de los sustantivos de mayor carga teológica en las Escrituras. Siempre plural en forma (un llamado plurale tantum), abarca el cielo visible donde vuelan las aves y cae la lluvia, la bóveda cósmica del sol, la luna y las estrellas, y la morada trascendente de Dios. El superlativo en constructo שְׁמֵי הַשָּׁמַיִם («cielos de los cielos», Dt 10:14; 1 R 8:27) expresa lo que ni siquiera Salomón pudo contener. Interlingüísticamente la palabra se traduce con notable uniformidad: español «cielos», francés «cieux», alemán «Himmel», árabe سَمَاء, preservando todos una ambigüedad similar entre cielo físico y morada divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8065', 'spa', 'Cielo(s), firmamento -- la forma aramea de shamayim, que designa el cielo visible o la morada celestial de Dios', 'Cielo(s), firmamento -- la forma aramea de shamayim, que designa el cielo visible o la morada celestial de Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8066', 'spa', 'Octavo — el número ordinal ocho, que marca días litúrgicos, meses del calendario y divisiones sacerdotales', 'Octavo — el número ordinal ocho, que marca días litúrgicos, meses del calendario y divisiones sacerdotales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8067', 'spa', 'el octavo, Seminit (término musical o número ordinal)', 'Este adjetivo significa ''octavo'' y aparece tanto como ordinal ordinario (el octavo día, el octavo mes) como término musical misterioso en títulos de salmos. En contextos rituales marca el octavo día de ceremonias (Éxodo 22:29 y muchos textos levíticos) o el octavo mes en la cronología de construcción real (1 Reyes 6:38). Más enigmáticamente, aparece en 1 Crónicas 15:21 describiendo levitas tocando arpas ''sobre Seminit,'' y en los títulos de los Salmos 6 y 12. Los estudiosos debaten si esto indica una octava, una clave o modo musical particular, o un instrumento de ocho cuerdas, pero el significado permanece incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8068', 'spa', 'Espinos, abrojos (colectivo); diamante, pedernal o esmeril (piedra muy dura)', 'El sustantivo שָׁמִיר presenta una de las escisiones semánticas más notables del hebreo bíblico, designando dos realidades físicas completamente distintas. En los oráculos de juicio de Isaías denota espinos y abrojos: la vegetación silvestre que invade viñedos abandonados y tierras desoladas (Is 5:6; 7:23-25; 27:4). Sin embargo, en Jeremías y Ezequiel se refiere a un mineral extremadamente duro —diamante, pedernal o esmeril— usado como metáfora de permanencia y obstinación: el pecado de Judá está grabado con «punta de diamante» (Jer 17:1), y Dios hace la frente del profeta más dura que el pedernal (Ez 3:9). Si se trata de una sola palabra con dos significados o de dos raíces originalmente distintas sigue siendo objeto de debate.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8069', 'spa', 'Samir (nombre de lugar: dos ciudades en Israel)', 'Samir designa dos ubicaciones distintas en el antiguo Israel. La primera, en la región montañosa de Efraín, sirvió como hogar y lugar de sepultura del juez Tola (Jueces 10:1-2). La segunda aparece en la asignación tribal de Judá, listada entre las ciudades de la región montañosa (Josué 15:48). El nombre probablemente deriva de una raíz que significa ''espina'' o ''pedernal,'' aunque la conexión es incierta. Las versiones griegas lo traducen de varias formas como Samir, Sameir, o incluso Samaria (en el contexto de Tola), mostrando cierta confusión geográfica en la transmisión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8070', 'spa', 'Semiramot; nombre levítico que posiblemente significa ''alturas del cielo''', 'Semiramot es un nombre propio llevado por al menos dos levitas en el Antiguo Testamento. Según el Thesaurus, el nombre podría significar ''alturas'' o ''nombre de las alturas'', quizás en referencia a los cielos. Un Semiramot sirvió como músico en la procesión de David cuando el arca fue llevada a Jerusalén (1 Cr 15:18, 20; 16:5), y otro fue un levita maestro enviado por el rey Josafat para instruir al pueblo (2 Cr 17:8). La LXX lo translitea como Σαμειραμωθ.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8071', 'spa', 'Vestidura exterior, manto; tambien una tela usada para envolver o cargar objetos', 'Vestidura exterior, manto; tambien una tela usada para envolver o cargar objetos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8072', 'spa', 'Samla; nombre propio de un rey edomita que reinó antes de que Israel tuviera reyes', 'Este es el nombre de uno de los primeros reyes de Edom enumerados en Génesis 36 y 1 Crónicas 1. La fórmula genealógica es típica: «Cuando murió [el rey anterior], reinó en su lugar Samla de Masreca». Estos reyes edomitas reinaron «antes de que reinara rey alguno sobre los hijos de Israel», situándolos en el período premonárquico. La etimología de Samla es incierta. Este rey no es conocido fuera de estas listas, pero la preservación de la sucesión real edomita en las Escrituras hebreas resulta notable, pues reconoce el desarrollo político paralelo de la nación hermana de Israel, descendiente de Esaú.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8074', 'spa', 'Estar desolado, quedar en ruinas; quedar espantado, horrorizado; causativo: devastar, dejar desolado; como participio: desolador. Pocas raíces hebreas', 'Estar desolado, quedar en ruinas; quedar espantado, horrorizado; causativo: devastar, dejar desolado; como participio: desolador. Pocas raíces hebreas llevan una doble carga tan poderosa como שָׁמֵם. Por un lado está la desolación física: ciudades reducidas a escombros, tierras de cultivo devueltas a la espesura, santuarios profanados y abandonados. Por otro está la respuesta humana visceral ante tal ruina: el horror, el silencio atónito, la incapacidad de procesar lo que los ojos contemplan. Cuando los exiliados en Esdras 9:3-4 se enteran de los matrimonios mixtos, se quedan «espantados» — la misma raíz que describe la tierra quedando «desolada» durante los años sabáticos que le fueron negados (Lv 26:34-35). La «abominación desoladora» de Daniel (Dn 9:27; 11:31; 12:11) fusiona ambos polos: un desolador que causa devastación y produce horror. La raíz traza así todo un paisaje emocional-físico desde la causa al efecto y de ahí a la respuesta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8076', 'spa', 'Desolado, asolado; describe un estado de ruina o abandono aplicado a tierras, santuarios y personas desvalidas.', 'Participio Qal de la raíz שָׁמֵם que retrata algo o alguien en condición de desolación y ruina. La palabra aparece en contextos tanto de devastación física como de abandono emocional. En Jeremías 12:11, la tierra misma llora porque yace desolada, mientras que en Lamentaciones 1:13 y 3:11 el término describe a una persona aturdida y desvalida. Las traducciones al español (desolada) y al francés (désolation) reflejan la misma amplitud, abarcando tanto el páramo geográfico como la devastación interior humana. La forma participial confiere una cualidad descriptiva y continua: la desolación no es un evento puntual, sino un estado permanente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8077a', 'spa', 'Desolación, devastación, ruina; en sentido abstracto, el estado de haber sido asolado; en sentido concreto (plural), los lugares desolados o las ruina', 'Desolación, devastación, ruina; en sentido abstracto, el estado de haber sido asolado; en sentido concreto (plural), los lugares desolados o las ruinas mismas. Sustantivo que expresa la condición y el resultado de la devastación, presente de manera prominente en los juicios proféticos de Jeremías y Ezequiel. En su sentido abstracto nombra el estado de quedar asolado: ciudades vaciadas, tierras vueltas yermas, poblaciones deportadas. Fórmulas proféticas como ''haré de esta ciudad una שְׁמָמָה'' se repiten decenas de veces. En su forma plural concreta designa los lugares arruinados mismos, como cuando Daniel ora por ''nuestras desolaciones'' (Dn 9:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8080', 'spa', 'Engordar, prosperar; en Hifil, hacer engordar o embotar, volver insensible', 'Este verbo abarca las dimensiones fisica y metaforica de la gordura en el pensamiento hebreo. En el Qal, describe a Israel engordando y volviendose rebelde bajo la bendicion divina (Dt 32:15), o a los malvados creciendo lustrosos y satisfechos (Jer 5:28). El Hifil porta un sentido causativo: en Nehemias 9:25 el pueblo ''se engordo'' por la abundancia, mientras que en Isaias 6:10 Dios ordena al profeta ''engordar'' -- es decir, volver torpe e insensible -- el corazon del pueblo. El castellano ''engordarse'' preserva bien la imagen concreta detras de la metafora teologica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8081', 'spa', 'Aceite, grasa, ungüento; aceite de oliva para unción, ofrendas, cocina e iluminación; también fertilidad y aceite perfumado', 'שֶׁמֶן es el oro líquido de la economía y el culto del antiguo Israel. Jacob lo derrama sobre la piedra en Betel (Gn 28:18), los sacerdotes lo mezclan con las ofrendas de cereal (Lv 2:1) y las lámparas lo queman cada noche en el tabernáculo (Éx 25:6). Pero la palabra se extiende mucho más allá del lagar. Isaías la emplea figuradamente para la feracidad de una ladera fértil (Is 5:1) y los manjares suntuosos del banquete mesiánico (Is 25:6). En el Cantar de los Cantares, el plural שְׁמָנִים se convierte en ungüento perfumado — «tus ungüentos son agradables» (Cnt 1:3) —, un cosmético de lujo muy distante del aceite de cocina. El español desdobla la diferencia con precisión entre «aceite» (ritual y culinario) y «ungüentos» (cosméticos), mientras que el alemán usa «Öl» para ambos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8082', 'spa', 'Gordo, rico, fértil; describe tierra productiva, alimentos suntuosos o personas y animales robustos y bien alimentados.', 'Adjetivo sensorial que evoca abundancia y vitalidad en el mundo físico. Jacob bendice a Aser con ''alimento rico'' de su territorio (Gn 49:20), los espías informan que el suelo de Canaán es ''fértil'' (Nm 13:20), y Ezequiel describe a Dios pastoreando tanto a las ovejas ''gordas como a las fuertes'' de su rebaño (34:16). El español ''fértil'' marca con claridad el sentido agrícola, mientras que ''robusto'' distingue el sentido corporal. La palabra no conlleva connotación negativa: la gordura aquí es siempre bendición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8083', 'spa', 'Ocho (número cardinal); se usa de forma independiente y en compuestos como dieciocho y ochenta', 'שְׁמֹנֶה es el número cardinal ocho en hebreo, con formas masculina (שְׁמֹנָה) y femenina (שְׁמֹנֶה) según el género gramatical del sustantivo que modifica. Aparece con frecuencia en los registros genealógicos (Gn 5:4, 7, 10), en medidas y en números compuestos como dieciocho (שְׁמֹנֶה עָשָׂר). La forma afín שְׁמֹנִים produce ''ochenta''. Las traducciones a otras lenguas lo reflejan de manera directa: español ''ocho'', francés ''huit'', alemán ''acht'', a veces precedido de la conjunción copulativa en las cadenas constructas propias de la sintaxis numérica hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8084', 'spa', 'Ochenta -- el numeral cardinal usado en edades, censos, medidas y calculos cronologicos', 'Ochenta -- el numeral cardinal usado en edades, censos, medidas y calculos cronologicos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8085', 'spa', 'Oír, escuchar, atender, obedecer; en Hifil: hacer oír, proclamar; en Nifal: ser oído', 'El verbo שָׁמַע codifica una progresión desde la percepción pasiva hasta la obediencia activa, algo central en la teología bíblica. Con más de 1.150 apariciones, transita desde simplemente oír un sonido, pasando por escuchar con atención deliberada, hasta obedecer lo escuchado: un espectro que la famosa oración del Shemá (Dt 6:4) explota magistralmente, ya que ''Oye, Israel'' exige simultáneamente atención auditiva, comprensión intelectual y obediencia al pacto. El Hifil causativo añade la dimensión de proclamación, mientras que el Nifal pasivo capta sonidos y famas que ''se oyen'' sin agente explícito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8086', 'spa', 'Arameo: oír, percibir escuchando; en Hitpael, obedecer o mostrarse sumiso a la autoridad.', 'El cognado arameo del hebreo שָׁמַע, que aparece exclusivamente en el libro de Daniel. En la conjugación Pe''al abarca toda la gama de la percepción auditiva: oír el sonido de cuerno, flauta y lira como señal para adorar la imagen de oro de Nabucodonosor (Dn 3:5, 7, 10, 15), y oír un informe sobre las habilidades de alguien (Dn 5:14, 16; 6:15). El Hitpael reflexivo en Dn 7:27 extiende el oír hacia la obediencia — ''todos los dominios le servirán y obedecerán'' — donde escuchar se convierte en sumisión activa. El español ''oír/obedecer'' traza el mismo arco semántico del oído a la voluntad, universal en las lenguas semíticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8087', 'spa', 'Sema; nombre propio masculino que significa ''oido, informe'', portado por varios israelitas', 'Sema es un nombre propio derivado de la raiz שׁמע (''oir'') que aparece en diversas genealogias tribales. Un Sema pertenece a la tribu de Juda como descendiente de Caleb (1 Cr 2:43-44), otro a Ruben (1 Cr 5:8) y un tercero a Benjamin (1 Cr 8:13, posiblemente identico con Simei en el v. 21). Un Sema postexilico se encuentra junto a Esdras durante la lectura publica de la Tora (Neh 8:4). La LXX transcribe el nombre de diversas formas, como Σαμα o Σαμαα.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8088b', 'spa', 'Informe, fama, o el acto de oír; lo que se escucha acerca de una persona, noticias que llegan, o el momento de percibir por el oído.', 'Informe, fama, o el acto de oír; lo que se escucha acerca de una persona, noticias que llegan, o el momento de percibir por el oído.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8089', 'spa', 'informe, fama; noticia o reputación que se difunde acerca de alguien o algo, especialmente por hechos notables', 'Este sustantivo designa un informe o fama que se propaga acerca de alguien. Josué 6:27 dice que «su fama se extendió por toda la tierra» tras la caída de Jericó. En Josué 9:9 los gabaonitas afirman haber venido «por la fama de YHWH tu Dios». Ester 9:4 señala que la fama de Mardoqueo se difundió por todas las provincias conforme crecía su poder. Jeremías 6:24 describe cómo al oír el informe del enemigo las manos desfallecen de temor. El término abarca tanto la transmisión de noticias como la reputación resultante: información que viaja y edifica el renombre de alguien, ya sea por los actos poderosos de Dios, las victorias de Josué o la autoridad de Mardoqueo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8092', 'spa', 'Simea; nombre propio, variante de Sama, portado por parientes de David y por levitas', 'Simea es una forma variante del nombre mas conocido Sama, derivado a su vez de la raiz שׁמע. El portador mas prominente es el hermano de David, tercer hijo de Isai (1 Cr 2:13), quien aparece bajo las formas Sama (1 S 16:9; 17:13), Simeah (2 S 13:3, 32) y Simea (2 S 21:21 Qere). Un hijo de David tambien lleva este nombre (1 Cr 3:5), al igual que dos levitas en las genealogias de 1 Cronicas 6. La LXX refleja multiples grafias griegas, entre ellas Σεμεει, Σαμαα y Σομεα.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8093', 'spa', 'Simea (nombre personal: hermano de David y otros)', 'Simea es un nombre personal que aparece en varias formas (Simea, Sama, Samúa) a través de genealogías y narrativas bíblicas. Más notablemente, fue el hermano de David, el tercer hijo de Isaí (1 Crónicas 2:13), llamado Sama en 1 Samuel 16:9 y 17:13. El nombre también se aplica a uno de los hijos de David nacidos en Jerusalén (1 Crónicas 3:5, paralelo a Samúa en el relato de Samuel) y a varios levitas (1 Crónicas 6:15, 24). Las versiones griegas muestran variación consonántica típica (Samaa, Semeei), reflejando la fluidez de las formas de nombres en la transmisión antigua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8095', 'spa', 'Simeon -- segundo hijo de Jacob y Lea; la tribu israelita descendiente de el', 'Simeon -- segundo hijo de Jacob y Lea; la tribu israelita descendiente de el');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8096', 'spa', 'Simei -- un benjaminita que maldijo a David, ademas de varios levitas, funcionarios y otros personajes biblicos', 'Simei -- un benjaminita que maldijo a David, ademas de varios levitas, funcionarios y otros personajes biblicos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8098', 'spa', 'Semaias -- nombre teoforico que significa ''Yahweh ha oido'', llevado por profetas, sacerdotes, levitas y otros', 'Semaias -- nombre teoforico que significa ''Yahweh ha oido'', llevado por profetas, sacerdotes, levitas y otros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8099', 'spa', 'simeonita; gentilicio que identifica a los miembros de la tribu de Simeón', 'Este es el gentilicio (adjetivo étnico-tribal) que significa «de la tribu de Simeón» o «perteneciente a los descendientes de Simeón». Aparece en contextos de censos y administración tribal. Números 25:14 identifica a Zimri como «jefe de una casa paterna de los simeonitas». Números 26:14 presenta los clanes simeonitas en el censo del desierto. Josué 21:4 menciona «la tribu de los simeonitas» en el reparto de ciudades levíticas. 1 Crónicas 27:16 enumera al «jefe de los simeonitas». Como ocurre con otros gentilicios tribales, este término marca la identidad dentro de la estructura de las doce tribus de Israel, aunque la historia de Simeón fue particular, pues su territorio acabó absorbido en gran medida por Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8104', 'spa', 'Guardar, vigilar, observar, custodiar, preservar; mantener custodia fiel sobre personas, cosas, mandamientos o pactos', 'Uno de los grandes verbos del pacto en la Biblia hebrea, שָׁמַר entrelaza el acto físico de vigilar con el acto moral de obedecer en un solo lexema. Un pastor guarda su rebaño, un centinela guarda las murallas e Israel guarda los mandamientos, todo con el mismo verbo. El Nifal reflexivo (''guárdate'') y el Hitpael intensivo (''guardarse a sí mismo'') extienden el campo semántico hacia el interior, convirtiendo la autovigilancia en disciplina espiritual. A lo largo de 469 apariciones, שָׁמַר fundamenta la convicción bíblica de que la fidelidad no es creencia pasiva sino custodia activa y vigilante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8105', 'spa', 'Heces, sedimento del vino; usado figuradamente para la complacencia o el banquete suntuoso', 'Usado exclusivamente en plural, este sustantivo designa las heces o sedimento que se deposita cuando el vino reposa sin ser trasvasado. Isaias 25:6 describe el banquete mesianico con ''vinos sobre sus heces'' -- anejos, clarificados, de suprema calidad. Pero la misma imagen tiene un filo mas oscuro: Jeremias 48:11 compara la existencia imperturbada de Moab con vino nunca trasegado, y Sofonias 1:12 advierte contra los que ''se han espesado sobre sus heces'', paralizados en su complacencia. El Salmo 75:8 emplea las heces de la copa de Dios como imagen del juicio apurado hasta la ultima gota.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8106', 'spa', 'Semer; nombre propio, especialmente el dueno original de la colina donde se edifico Samaria', 'Semer es conocido ante todo como el hombre a quien el rey Omri compro la colina que se convirtio en Samaria, capital del reino del norte de Israel (1 R 16:24). El nombre de la ciudad שֹׁמְרוֹן deriva explicitamente de esta compra. Mas alla de esta figura historicamente decisiva, el nombre aparece en genealogias leviticas y tribales: un levita en 1 Cronicas 6:46, un miembro de Aser (1 Cr 7:34, variante Somer en el v. 32) y posiblemente un benjaminita (1 Cr 8:12). La LXX lo transcribe como Σεμμηρ o Σωμηρ.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8110b', 'spa', 'Simrón (nombre personal: cuarto hijo de Isacar y ancestro del clan simronita)', 'Simrón fue el cuarto hijo de Isacar, mencionado en las genealogías patriarcales. Aparece en el registro familiar cuando la casa de Jacob descendió a Egipto (Génesis 46:13), en el censo del desierto como fundador del clan simronita (Números 26:24), y en el registro genealógico de Crónicas (1 Crónicas 7:1). El nombre deriva de una raíz que significa ''vigilar'' o ''guardar''. Las versiones griegas muestran variación considerable (Zambram, Sambra, Semerón), típico de los desafíos al transliterar nombres hebreos. Este nombre personal debe distinguirse de la ciudad cananea Simrón (Josué 11:1) y Simrón-merón (Josué 12:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8111', 'spa', 'Samaria (שֹׁמְרוֹן) — ciudad capital del reino del norte de Israel; también la región circundante', 'שֹׁמְרוֹן (Samaria) designa tanto la ciudad fortificada en lo alto de la colina que el rey Omri compró y edificó como capital del reino del norte (1 R 16:24) como, por extensión, el territorio circundante. La ciudad sirvió de centro político y religioso de Israel durante toda la monarquía dividida, destacándose en los relatos de Elías y Eliseo y en los oráculos proféticos de juicio. Ezequiel la personifica como mujer junto a Jerusalén (Ez 16:46; 23:4). La conquista asiria de Samaria en 722 a. C. marcó el fin del reino del norte. Las traducciones conservan el topónimo de forma transparente: español Samaria, francés Samarie, alemán Samarien.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8113', 'spa', 'Simri; nombre propio de varios individuos, entre ellos un simeonita, el padre de un guerrero de David y levitas', 'Este nombre propio aparece para varios individuos en Crónicas. 1 Crónicas 4:37 menciona a un Simri en una genealogía simeonita. 1 Crónicas 11:45 identifica a Simri como el padre de Jediael, uno de los guerreros valientes de David. 1 Crónicas 26:10 nombra a un Simri como portero levita. 2 Crónicas 29:13 registra a otro levita llamado Simri que participó en la purificación del templo bajo Ezequías. El nombre posiblemente deriva de la raíz שָׁמַר (guardar, custodiar), lo que sugiere significados como «mi guardián» o «vigilante». Su aparición en distintas tribus (Simeón, Leví) y contextos (genealogía, milicia, servicio del templo) indica que era un nombre relativamente común en el antiguo Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8114', 'spa', 'Semarías; nombre teofórico que significa «YHWH ha guardado/preservado», llevado por un guerrero de David y contemporáneos de Esdras', 'Este nombre teofórico (que contiene el nombre de Dios) significa «YHWH ha guardado» o «YHWH ha preservado». Aparece con variantes ortográficas: Semaryahu (con la terminación completa del nombre divino) en 1 Crónicas 12:6, donde designa a uno de los guerreros que se unieron a David en Siclag, y Semarías (forma abreviada) para un hijo de Roboam (2 Cr 11:19) y dos hombres que se habían casado con mujeres extranjeras en tiempos de Esdras (Esd 10:32, 41). El nombre expresa la gratitud de los padres por la protección o preservación divina, quizá del hijo o de la familia. Su presencia tanto entre los primeros seguidores de David como en la comunidad postexílica demuestra su uso perdurable a lo largo de la historia de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8115', 'spa', 'Samaria, Shomrayin (forma aramea del nombre de la ciudad/región)', 'Esta es la forma aramea de Samaria, la ciudad capital del reino del norte de Israel, que aparece en la correspondencia aramea de Esdras. El nombre ocurre en cartas de funcionarios provinciales al rey persa quejándose de la reconstrucción de Jerusalén (Esdras 4:10, 17). Para este período, Samaria designaba tanto la ciudad como la provincia circundante en el sistema administrativo persa. La palabra aparece en contextos que discuten política regional y tensiones étnicas, con funcionarios samaritanos oponiéndose a los esfuerzos de reconstrucción judea. Las glosas multilingües a veces simplemente transliteran ''Samaria'', reflejando el carácter de nombre propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8121', 'spa', 'El sol como cuerpo celeste, marcador temporal y símbolo de gloria; en un caso aislado, almenas u ornamentos arquitectónicos', 'שֶׁמֶשׁ es la palabra estándar de la Biblia hebrea para el sol, presente en contextos que van desde la poesía de la creación hasta la regulación legal. Funciona como el gran marcador temporal: el amanecer (זָרַח) y la puesta del sol (בּוֹא) enmarcan la vida diaria, los periodos de pureza ritual y los momentos del pacto como la visión de Abraham (Gn 15:12, 17). En sentido figurado, el sol representa la justicia de Dios (Mal 3:20, ''sol de justicia''), el esplendor real (Jue 5:31) y la exposición implacable de las obras ocultas (Ec 1:9). Un único uso enigmático en Isaías 54:12 emplea el plural שִׁמְשׁוֹת para rasgos arquitectónicos, probablemente almenas u ornamentos solares que coronan los muros de la Jerusalén escatológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8123', 'spa', 'Sansón — el juez danita cuyo nombre evoca ''sol'', famoso por su fuerza sobrenatural y su trágica caída', 'Sansón — el juez danita cuyo nombre evoca ''sol'', famoso por su fuerza sobrenatural y su trágica caída');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8124', 'spa', 'Simsai; nombre propio de un escriba que se opuso a la reconstrucción de Jerusalén en Esdras 4, probablemente de origen persa', 'Este nombre aparece exclusivamente en Esdras 4:8, 9, 17, 23, siempre acompañado del título «Simsai el escriba». Junto con Rehum el comandante, escribe al rey Artajerjes oponiéndose a la reconstrucción de los muros de Jerusalén; luego reciben la respuesta del rey y hacen cumplir la orden de detener las obras. El nombre es probablemente de origen persa o iranio antiguo (se han propuesto significados relacionados con «sol» o con connotaciones de generosidad), adaptado a la escritura hebrea. Como escriba de la administración persa, Simsai representa la oposición burocrática a la restauración judía, utilizando canales legales y políticos para bloquear lo que Dios había decretado por medio de Ciro.');